package com.gecopilot.client.api;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

/** Fetches an item's price history from the OSRS Wiki real-time prices API, asynchronously. */
public final class WikiTimeseries implements TimeseriesCache.Loader {
    static final String URL = "https://prices.runescape.wiki/api/v1/osrs/timeseries";
    static final String USER_AGENT = "Coffer RuneLite plugin - github.com/Paul2357/ge-copilot";
    static final long CALL_TIMEOUT_SEC = 10;
    /** A full 365-point series is ~40 KB; anything near this is not a timeseries. */
    static final long MAX_BODY_BYTES = 1L << 20;

    private final OkHttpClient http;
    private final Gson gson;

    /** Derives a client with a call timeout once; calls go through OkHttp's dispatcher, never the caller's thread. */
    public WikiTimeseries(OkHttpClient http, Gson gson) {
        this.http = http == null ? null : http.newBuilder().callTimeout(CALL_TIMEOUT_SEC, TimeUnit.SECONDS).build();
        this.gson = gson;
    }

    OkHttpClient client() { return http; }

    @Override
    public void load(int itemId, String timestep, TimeseriesCache.Callback cb) {
        HttpUrl url = HttpUrl.get(URL).newBuilder()
            .addQueryParameter("id", Integer.toString(itemId))
            .addQueryParameter("timestep", timestep)
            .build();
        Request req = new Request.Builder().url(url).header("User-Agent", USER_AGENT).get().build();
        http.newCall(req).enqueue(new Callback() {
            @Override public void onFailure(Call call, IOException e) { cb.onFailure(e); }

            @Override public void onResponse(Call call, Response res) {
                List<SparklineDto.Point> pts;
                try (Response r = res) {
                    if (!r.isSuccessful() || r.body() == null) throw new IOException("wiki timeseries HTTP " + r.code());
                    pts = parse(readCapped(r.body(), MAX_BODY_BYTES));
                } catch (Throwable t) {
                    cb.onFailure(t);
                    return;
                }
                cb.onSuccess(pts);
            }
        });
    }

    /** Reads the body as UTF-8, failing instead of buffering more than {@code max} bytes. */
    static String readCapped(ResponseBody body, long max) throws IOException {
        if (body.contentLength() > max) throw new IOException("wiki timeseries body too large: " + body.contentLength());
        BufferedSource src = body.source();
        if (src.request(max + 1)) throw new IOException("wiki timeseries body over " + max + " bytes");
        return src.getBuffer().readString(StandardCharsets.UTF_8);
    }

    /** {data:[{timestamp, avgHighPrice, avgLowPrice, ...}]} to points; null or out-of-range prices become 0. */
    public List<SparklineDto.Point> parse(String json) {
        List<SparklineDto.Point> out = new ArrayList<>();
        JsonObject o = gson.fromJson(json, JsonObject.class);
        if (o == null || !o.has("data") || !o.get("data").isJsonArray()) return out;
        for (JsonElement e : o.getAsJsonArray("data")) {
            if (!e.isJsonObject()) continue;
            JsonObject p = e.getAsJsonObject();
            SparklineDto.Point pt = new SparklineDto.Point();
            pt.ts = timestamp(p);
            pt.high = price(p, "avgHighPrice");
            pt.low = price(p, "avgLowPrice");
            if (pt.ts <= 0 || (pt.high == 0 && pt.low == 0)) continue;
            pt.highVol = count(p, "highPriceVolume");
            pt.lowVol = count(p, "lowPriceVolume");
            pt.mid = pt.high > 0 && pt.low > 0 ? (pt.high + pt.low) / 2.0 : Math.max(pt.high, pt.low);
            out.add(pt);
        }
        return out;
    }

    /** A GE price in 1..Integer.MAX_VALUE, else 0 (missing). */
    static long price(JsonObject o, String key) {
        JsonElement e = o.get(key);
        if (e == null || e.isJsonNull() || !e.isJsonPrimitive()) return 0;
        double d;
        try { d = e.getAsDouble(); } catch (NumberFormatException ex) { return 0; }
        // Range-check as a double: a huge integer read via getAsLong() can wrap back into range.
        return d >= 1 && d <= Integer.MAX_VALUE ? (long) d : 0;
    }

    /** Latest plausible epoch second (year 2286); anything else is treated as missing. */
    static final double MAX_TS = 9_999_999_999d;

    /** Unix seconds, range-checked as a double like prices; 0 when missing or out of range. */
    static long timestamp(JsonObject o) {
        double d = dbl(o, "timestamp");
        return d >= 1 && d <= MAX_TS ? (long) d : 0;
    }

    /** A trade count in 0..Integer.MAX_VALUE, else 0. */
    static long count(JsonObject o, String key) {
        double d = dbl(o, key);
        return d >= 0 && d <= Integer.MAX_VALUE ? (long) d : 0;
    }

    private static double dbl(JsonObject o, String key) {
        JsonElement e = o.get(key);
        if (e == null || e.isJsonNull() || !e.isJsonPrimitive()) return Double.NaN;
        try { return e.getAsDouble(); } catch (NumberFormatException ex) { return Double.NaN; }
    }
}

package com.gecopilot.client.auth;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermission;
import java.util.EnumSet;
import java.util.Optional;
import java.util.Set;

@Slf4j
public class TokenStore {
    private final Path file;

    // Hub policy: plugin file access must stay within a plugin subdir of RUNELITE_DIR (~/.runelite).
    public TokenStore() { this(RuneLite.RUNELITE_DIR.toPath().resolve("coffer").resolve("session")); }
    public TokenStore(Path file) { this.file = file; }

    public void save(String token) {
        try {
            if (file.getParent() != null) Files.createDirectories(file.getParent());
            Files.write(file, token.getBytes(StandardCharsets.UTF_8));
            try {
                Set<PosixFilePermission> perms = EnumSet.of(PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE);
                Files.setPosixFilePermissions(file, perms);
            } catch (UnsupportedOperationException | IOException ignore) { /* non-POSIX FS */ }
        } catch (IOException e) { log.warn("token save failed: {}", e.getMessage()); }
    }

    public Optional<String> load() {
        try {
            if (!Files.exists(file)) return Optional.empty();
            String t = new String(Files.readAllBytes(file), StandardCharsets.UTF_8).trim();
            return t.isEmpty() ? Optional.empty() : Optional.of(t);
        } catch (IOException e) { return Optional.empty(); }
    }

    public void clear() {
        try { Files.deleteIfExists(file); } catch (IOException ignore) { }
    }
}

package com.gecopilot.client.trade;

public class CompletedFill implements OwnedItem {
    public final int itemId;
    public final boolean buy;
    public final int qty, price;
    public final long ts;
    // RS display name that made the fill, stamped by the plugin after capture (null if unknown, e.g. an
    // offline fill replayed before login). Serialized with the durable pending queue.
    public String account;
    // Stable identity of the terminal offer (slot:epoch:signature). The server ignores a second post
    // with the same key, so a replayed fill can't double-count even if the client dedup misses it.
    public String fillKey;
    // Coffer user this fill belongs to (see QueueOwnership). Null in queues saved by older builds.
    public Long ownerId;

    public CompletedFill(int itemId, boolean buy, int qty, int price, long ts) {
        this.itemId = itemId;
        this.buy = buy;
        this.qty = qty;
        this.price = price;
        this.ts = ts;
    }

    @Override public Long getOwnerId() { return ownerId; }
    @Override public void setOwnerId(Long id) { ownerId = id; }
    @Override public long getTs() { return ts; }
}

package com.gecopilot.client.trade;

import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the in-game GE History interface (group 383, list container child 3). Its dynamic children
 * are, per completed trade: a "Bought:"/"Sold:" label, then within the next few slots the item widget
 * (authoritative itemId + quantity) and a "<total> coins … = <each> each" price line. Unit price is
 * computed as round(total/qty) to match how Coffer records fills (round(spent/qty)).
 *
 * Must be called on the client thread.
 */
public final class GeHistoryReader {
    private GeHistoryReader() {}

    private static final int GROUP = 383, LIST_CHILD = 3;
    private static final Pattern NUM = Pattern.compile("([\\d,]+)");
    private static final Pattern GROSS_PAREN = Pattern.compile("\\(([\\d,]+)\\s*-"); // "(729,632 - 14,592)"

    public static List<GeHistoryRow> read(Client client) {
        List<GeHistoryRow> out = new ArrayList<>();
        Widget list = client.getWidget(GROUP, LIST_CHILD);
        if (list == null) return out;
        Widget[] dyn = list.getDynamicChildren();
        if (dyn == null) return out;
        for (int i = 0; i < dyn.length; i++) {
            Widget w = dyn[i];
            String t = w == null ? null : w.getText();
            if (t == null) continue;
            boolean buy;
            if (t.equals("Bought:")) buy = true; else if (t.equals("Sold:")) buy = false; else continue;

            int itemId = -1, qty = 0; String priceText = null;
            for (int j = i + 1; j <= i + 5 && j < dyn.length; j++) {
                Widget c = dyn[j]; if (c == null) continue;
                if (itemId < 0 && c.getItemId() > 0) { itemId = c.getItemId(); qty = c.getItemQuantity(); }
                String ct = c.getText();
                if (priceText == null && ct != null && ct.contains("coins")) priceText = ct;
            }
            if (itemId > 0 && qty > 0 && priceText != null) {
                long gross = grossTotal(priceText);
                if (gross >= 0) out.add(new GeHistoryRow(itemId, buy, qty, (int) Math.round((double) gross / qty)));
            }
        }
        return out;
    }

    /**
     * The GROSS total coins for a history price line, matching how Coffer records fills (gross,
     * pre-tax). A sell shows "715,040 coins (729,632 - 14,592) = 89,380 each" — the 715,040 is net
     * and 729,632 (in parens) is gross; use the gross. A buy shows just "594,663 coins = …" with no
     * tax breakdown, so its plain total is already gross.
     */
    static long grossTotal(String priceText) {
        String s = priceText.replaceAll("<[^>]*>", " ");
        Matcher paren = GROSS_PAREN.matcher(s);
        if (paren.find()) return Long.parseLong(paren.group(1).replace(",", ""));
        return firstNumber(priceText);
    }

    /** First comma-grouped integer in a string ("594,663 coins…" -> 594663), or -1 if none. Strips
     *  HTML-ish tags first so digits inside colour codes (e.g. &lt;col=ffb83f&gt;) aren't matched. */
    static long firstNumber(String s) {
        Matcher m = NUM.matcher(s.replaceAll("<[^>]*>", " "));
        return m.find() ? Long.parseLong(m.group(1).replace(",", "")) : -1;
    }
}

package com.gecopilot.client.trade;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Pure reconcile step for GE History: given the trades read from the in-game History and the trades
 * already recorded, decide what to import and which recorded prices to correct.
 *
 * <p>Exact signature ({@code item:side:qty:unitPrice}) still wins, across the whole account, so a
 * repeated identical flip imports only the extra copies and a second open of History is a no-op.
 *
 * <p>A live fill often lands at the <em>offer</em> price ({@code spent == offer × qty} on the first
 * observation) while History shows the coins that actually moved. Those rows do not share a
 * signature, so the old count match imported History on top of the live row — the sell was counted
 * twice, and the live price stayed wrong. When exactly the same item, side, and qty is left over on
 * both sides and the prices are within {@link #PRICE_BAND_NUMER}/{@link #PRICE_BAND_DENOM} of each
 * other, History corrects the recorded price instead of inserting another trade. The GE History list
 * is only the last {@link #HISTORY_WINDOW} listings, so a correction may only touch a recorded trade
 * inside that newest window; an older flip of the same quantity is left alone and the History row
 * is imported.
 */
public final class GeHistoryReconcile {
    private GeHistoryReconcile() {}

    /** In-game History keeps the last 40 listings (since the 2019 expansion). */
    static final int HISTORY_WINDOW = 40;
    /** Prices within 25% of the higher one can be the same fill (offer vs actual). */
    static final int PRICE_BAND_NUMER = 1;
    static final int PRICE_BAND_DENOM = 4;

    /** A raw recorded trade from GET /api/trades/mine (server's source of truth). */
    public static final class Recorded {
        public int itemId; public boolean buy; public int qty; public int price;
        /** Epoch ms. 0 when the server didn't send one — then every row is "recent". */
        public long ts;
    }

    /** History's unit price replaces a recorded offer price on the same item/side/qty. */
    public static final class Correction {
        public final int itemId;
        public final boolean buy;
        public final int qty;
        public final int fromPrice;
        public final int toPrice;

        public Correction(int itemId, boolean buy, int qty, int fromPrice, int toPrice) {
            this.itemId = itemId; this.buy = buy; this.qty = qty;
            this.fromPrice = fromPrice; this.toPrice = toPrice;
        }
    }

    /** What to do with one History read. Both lists may be empty (already in sync). */
    public static final class Plan {
        public final List<GeHistoryRow> imports;
        public final List<Correction> corrections;

        public Plan(List<GeHistoryRow> imports, List<Correction> corrections) {
            this.imports = imports;
            this.corrections = corrections;
        }
    }

    private static String sig(int itemId, boolean buy, int qty, int price) {
        return itemId + ":" + (buy ? "B" : "S") + ":" + qty + ":" + price;
    }

    private static String bucket(int itemId, boolean buy, int qty) {
        return itemId + ":" + (buy ? "B" : "S") + ":" + qty;
    }

    /** Gap is at most a quarter of the higher price (about 33% above the lower). */
    static boolean withinBand(int a, int b) {
        if (a <= 0 || b <= 0) return false;
        long max = Math.max(a, b);
        long diff = Math.abs((long) a - b);
        return diff * PRICE_BAND_DENOM <= max * PRICE_BAND_NUMER;
    }

    /** History rows that are not already covered by recorded trades, preserving History order. */
    public static List<GeHistoryRow> missing(List<GeHistoryRow> history, List<Recorded> recorded) {
        return plan(history, recorded).imports;
    }

    public static Plan plan(List<GeHistoryRow> history, List<Recorded> recorded) {
        List<Recorded> all = recorded == null ? new ArrayList<Recorded>() : recorded;
        Map<String, ArrayDeque<Recorded>> exact = new HashMap<>();
        for (Recorded r : all) exact.computeIfAbsent(sig(r.itemId, r.buy, r.qty, r.price), k -> new ArrayDeque<>()).add(r);

        List<GeHistoryRow> unmatched = new ArrayList<>();
        Set<Recorded> exactConsumed = new HashSet<>();
        if (history != null) {
            for (GeHistoryRow h : history) {
                ArrayDeque<Recorded> q = exact.get(sig(h.itemId, h.buy, h.qty, h.unitPrice));
                if (q != null && !q.isEmpty()) exactConsumed.add(q.removeFirst());
                else unmatched.add(h);
            }
        }

        List<Recorded> recent = recentWindow(all);
        Map<String, List<Recorded>> recBy = new HashMap<>();
        for (Recorded r : recent) {
            if (exactConsumed.contains(r)) continue;
            recBy.computeIfAbsent(bucket(r.itemId, r.buy, r.qty), k -> new ArrayList<>()).add(r);
        }
        Map<String, List<GeHistoryRow>> histBy = new HashMap<>();
        for (GeHistoryRow h : unmatched) histBy.computeIfAbsent(bucket(h.itemId, h.buy, h.qty), k -> new ArrayList<>()).add(h);

        Set<GeHistoryRow> paired = new HashSet<>();
        List<Correction> corrections = new ArrayList<>();
        for (Map.Entry<String, List<GeHistoryRow>> e : histBy.entrySet()) {
            List<GeHistoryRow> hs = e.getValue();
            List<Recorded> rs = recBy.containsKey(e.getKey()) ? recBy.get(e.getKey()) : new ArrayList<Recorded>();
            boolean[] tookH = new boolean[hs.size()];
            boolean[] usedR = new boolean[rs.size()];
            while (true) {
                int bi = -1, bj = -1;
                long best = Long.MAX_VALUE;
                for (int i = 0; i < hs.size(); i++) {
                    if (tookH[i]) continue;
                    for (int j = 0; j < rs.size(); j++) {
                        if (usedR[j]) continue;
                        if (!withinBand(hs.get(i).unitPrice, rs.get(j).price)) continue;
                        long diff = Math.abs((long) hs.get(i).unitPrice - rs.get(j).price);
                        if (diff < best) { best = diff; bi = i; bj = j; }
                    }
                }
                if (bi < 0) break;
                tookH[bi] = true;
                usedR[bj] = true;
                GeHistoryRow h = hs.get(bi);
                Recorded r = rs.get(bj);
                paired.add(h);
                if (r.price != h.unitPrice) corrections.add(new Correction(h.itemId, h.buy, h.qty, r.price, h.unitPrice));
            }
        }

        List<GeHistoryRow> imports = new ArrayList<>();
        for (GeHistoryRow h : unmatched) if (!paired.contains(h)) imports.add(h);
        return new Plan(imports, corrections);
    }

    /** Newest {@link #HISTORY_WINDOW} recorded trades. Without timestamps, keep the whole list. */
    private static List<Recorded> recentWindow(List<Recorded> all) {
        boolean anyTs = false;
        for (Recorded r : all) if (r.ts > 0) { anyTs = true; break; }
        if (!anyTs || all.size() <= HISTORY_WINDOW) return all;
        List<Recorded> sorted = new ArrayList<>(all);
        sorted.sort((a, b) -> Long.compare(b.ts, a.ts));
        return new ArrayList<>(sorted.subList(0, HISTORY_WINDOW));
    }

    /** Banner copy for a non-empty plan. */
    public static String prompt(Plan plan) {
        int nImp = plan.imports.size();
        int nCor = plan.corrections.size();
        if (nImp > 0 && nCor > 0) {
            return nImp + " missed, " + nCor + " price" + (nCor == 1 ? "" : "s") + " to fix";
        }
        if (nCor > 0) {
            return nCor + " trade price" + (nCor == 1 ? "" : "s") + " don't match GE History";
        }
        return nImp + " GE History trade" + (nImp == 1 ? "" : "s") + " not recorded";
    }
}

