import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.function.BooleanSupplier;

/**
 * Price chart over the chatbox while the GE "Set up offer" or "Offer status" screen is open.
 * Built and registered by the plugin in startUp() and removed in shutDown(): it has no injected
 * members, so it can't attach itself to the client while Coffer is disabled.
 */
public class OfferChartOverlay extends Overlay {
    static final int CURRENT_GE_ITEM = 1151;
    /** Price typed on the GE setup screen (VarPlayer GE_NEWOFFER_PRICE; long since max-cash offers). */
    static final int VARP_GE_NEWOFFER_PRICE = VarPlayerID.GE_NEWOFFER_PRICE;
    static final int MESLAYER_INT_INPUT = 7;
    static final int MESLAYER_LONG_INPUT = 30;
    static final String ITEM_SEARCH_PROMPT = "What would you like to buy?";
    private static final Rectangle[] NO_TABS = new Rectangle[0];
    static final int MIN_HEIGHT = 70;

    private final Client client;
    private final TimeseriesCache cache;
    private final BooleanSupplier enabled;
    private final OfferChart.Model model = new OfferChart.Model();
    private final MouseListener mouse = new TabClicks();
    private volatile QuoteDto quote;
    private volatile OfferChartRange range = OfferChartRange.DAY;
    private volatile int hoverTab = -1;
    private volatile Point hover; // mouse position while logged in, for the crosshair tooltip
    volatile Rectangle[] tabs = NO_TABS; // last frame's tab hit boxes; package-visible for tests

    public OfferChartOverlay(Client client, TimeseriesCache cache, BooleanSupplier enabled) {
        this.client = client;
        this.cache = cache;
        this.enabled = enabled;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_LOW);
    }

    public void setQuote(QuoteDto q) { this.quote = q; }

    /** Tab clicks; the plugin registers this with the MouseManager alongside the overlay. */
    public MouseListener mouseListener() { return mouse; }

    /** Shown only with the config toggle on, an item on the GE offer/status screen, and no chatbox prompt over it. */
    static boolean visible(boolean enabled, int itemId, String geFrameText, int mesLayerMode, String chatPrompt) {
        if (!enabled || itemId <= 0) return false;
        if (!isOfferScreen(geFrameText)) return false;
        if (mesLayerMode == MESLAYER_INT_INPUT || mesLayerMode == MESLAYER_LONG_INPUT) return false;
        return chatPrompt == null || !chatPrompt.contains(ITEM_SEARCH_PROMPT);
    }

    static boolean isOfferScreen(String geFrameText) {
        return geFrameText != null && (geFrameText.contains("Set up offer") || geFrameText.contains("Offer status"));
    }

    @Override
    public Dimension render(Graphics2D g) {
        GrandExchangeOffer slotOffer = selectedSlotOffer(client);
        int itemId = activeItemId(client);
        Widget prompt = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
        if (!visible(enabled.getAsBoolean(), itemId, geFrameText(),
            client.getVarcIntValue(VarClientID.MESLAYERMODE), prompt == null ? null : prompt.getText())) {
            hide();
            return null;
        }
        Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
        Widget chatArea = client.getWidget(InterfaceID.Chatbox.CHATAREA);
        if (chatbox == null || chatbox.isHidden() || (chatArea != null && chatArea.isHidden())) {
            hide(); // chat collapsed in resizable mode: nothing to sit on
            return null;
        }
        Widget ge = client.getWidget(InterfaceID.GeOffers.FRAME);
        Rectangle area = fitBelow(chatbox.getBounds(), ge == null || ge.isHidden() ? null : ge.getBounds(), MIN_HEIGHT);
        if (area == null || area.width < 120) { hide(); return null; }

        OfferChartRange r = range;
        TimeseriesCache.Series s = cache.get(itemId, r.timestep);
        QuoteDto q = quote;
        model.range = r;
        model.points = s == null ? null : s.points;
        model.failed = s != null && s.failed;
        model.dataAgeSec = s == null ? 0 : Math.max(0, (cache.nowMs() - s.dataAtMs) / 1000L);
        model.hoverTab = hoverTab;
        model.hover = hover;
        model.nowSec = System.currentTimeMillis() / 1000L;
        model.offerPrice = offerPrice(slotOffer, client.getVarpLongValue(VARP_GE_NEWOFFER_PRICE));
        model.quote = q != null && q.id == itemId ? q : null;
        tabs = OfferChart.paint(g, area, model, FontManager.getRunescapeSmallFont());
        return new Dimension(area.width, area.height);
    }

    /** Not drawn this frame: drop tab hit boxes and hover so a stale tooltip can't reappear. */
    private void hide() {
        tabs = NO_TABS;
        hoverTab = -1;
        hover = null;
    }

    /**
     * The item the GE screen is about: the selected slot's active offer (Offer status), else the item
     * picked on Set up offer. The plugin quotes this same id, so Coffer's lines show on both screens.
     * Client thread only.
     */
    public static int activeItemId(Client client) {
        return activeItemId(client.getVarbitValue(VarbitID.GE_SELECTEDSLOT), client.getGrandExchangeOffers(),
            client.getVarpValue(CURRENT_GE_ITEM));
    }

    static int activeItemId(int selectedSlot1Based, GrandExchangeOffer[] offers, int setupItem) {
        GrandExchangeOffer o = slotOffer(selectedSlot1Based, offers);
        return o != null ? o.getItemId() : setupItem;
    }

    /** The active offer's price, else the price typed on Set up offer; 0 (no line) when unset. */
    static long offerPrice(GrandExchangeOffer slotOffer, long setupPrice) {
        long v = slotOffer != null ? slotOffer.getPrice() : setupPrice;
        return v > 0 ? v : 0;
    }

    private static GrandExchangeOffer selectedSlotOffer(Client client) {
        return slotOffer(client.getVarbitValue(VarbitID.GE_SELECTEDSLOT), client.getGrandExchangeOffers());
    }

    /** The existing offer in the selected GE slot (GE_SELECTEDSLOT is 1-based; 0 = none). */
    static GrandExchangeOffer slotOffer(int selectedSlot1Based, GrandExchangeOffer[] offers) {
        int slot = selectedSlot1Based - 1;
        if (offers == null || slot < 0 || slot >= offers.length) return null;
        GrandExchangeOffer o = offers[slot];
        return o != null && o.getItemId() > 0 ? o : null;
    }

    private String geFrameText() {
        Widget frame = client.getWidget(InterfaceID.GeOffers.FRAME);
        if (frame == null) return null;
        Widget[] kids = frame.getDynamicChildren();
        if (kids == null) return null;
        StringBuilder sb = new StringBuilder();
        for (Widget w : kids) if (w != null && w.getText() != null) sb.append(w.getText()).append('\n');
        return sb.toString();
    }

    /**
     * The chatbox area, shortened to start below the GE window if that overlaps it (small resizable
     * layouts), or null when what's left is under {@code minHeight}.
     */
    static Rectangle fitBelow(Rectangle chat, Rectangle ge, int minHeight) {
        if (chat == null || chat.isEmpty()) return null;
        if (ge == null || ge.isEmpty() || !ge.intersects(chat)) return chat.height >= minHeight ? chat : null;
        int top = ge.y + ge.height;
        int height = chat.y + chat.height - top;
        return height >= minHeight ? new Rectangle(chat.x, top, chat.width, height) : null;
    }

    /** Index into {@link OfferChartRange#values()} of the tab under {@code p}, or -1. */
    static int tabAt(Rectangle[] tabs, Point p) {
        if (tabs == null || p == null) return -1;
        for (int i = 0; i < tabs.length; i++) if (tabs[i].contains(p)) return i;
        return -1;
    }

    /** Tab under {@code p}, but only while logged in (the chart can't be on screen otherwise). */
    static int clickedTab(GameState state, Rectangle[] tabs, Point p) {
        return state == GameState.LOGGED_IN ? tabAt(tabs, p) : -1;
    }

    OfferChartRange range() { return range; }

    Point hover() { return hover; }

    private final class TabClicks extends MouseAdapter {
        @Override
        public MouseEvent mousePressed(MouseEvent e) {
            int i = clickedTab(client.getGameState(), tabs, e.getPoint());
            if (i < 0) return e;
            range = OfferChartRange.values()[i];
            e.consume();
            return e;
        }

        @Override
        public MouseEvent mouseMoved(MouseEvent e) {
            boolean in = client.getGameState() == GameState.LOGGED_IN;
            hoverTab = in ? tabAt(tabs, e.getPoint()) : -1;
            hover = in ? e.getPoint() : null;
            return e;
        }

        @Override
        public MouseEvent mouseExited(MouseEvent e) {
            hoverTab = -1;
            hover = null;
            return e;
        }

        @Override
        public MouseEvent mouseReleased(MouseEvent e) {
            if (clickedTab(client.getGameState(), tabs, e.getPoint()) >= 0) e.consume();
            return e;
        }

        @Override
        public MouseEvent mouseClicked(MouseEvent e) {
            if (clickedTab(client.getGameState(), tabs, e.getPoint()) >= 0) e.consume();
            return e;
        }
    }
}

package com.gecopilot.client.ui;

/** The offer chart's tabs, each mapped to the OSRS Wiki timeseries timestep that covers it. */
public enum OfferChartRange {
    DAY("1d", "5m", 5L * 60, 24L * 60 * 60),
    WEEK("1w", "1h", 60L * 60, 7L * 24 * 60 * 60),
    MONTH("1m", "6h", 6L * 60 * 60, 30L * 24 * 60 * 60),
    YEAR("1y", "24h", 24L * 60 * 60, 365L * 24 * 60 * 60);

    public final String label;
    public final String timestep;
    public final long stepSec;
    public final long windowSec;

    OfferChartRange(String label, String timestep, long stepSec, long windowSec) {
        this.label = label;
        this.timestep = timestep;
        this.stepSec = stepSec;
        this.windowSec = windowSec;
    }
}

package com.gecopilot.client.ui;

import java.text.NumberFormat;

/**
 * Non-blocking check for the GE offer-setup screen.
 *
 * The prices are the ones the plugin already fetched for the overlay quote, not a new request:
 * {@code marketLow} is {@code quote.buy} (what buyers are paying now — hour average low, else latest
 * low) and {@code marketHigh} is {@code quote.sell} (hour average high, else latest high).
 *
 * A sell below that low would fill for less than buyers are paying right now. A buy above that
 * high would pay more than the current market high.
 */
public final class OfferPriceWarning {
    private static final NumberFormat GP = NumberFormat.getIntegerInstance();

    private OfferPriceWarning() {}

    public static final class Warning {
        public final boolean buy;
        public final int offerPrice;
        public final int marketPrice;
        public final int gapGp;
        public final double gapPct;

        Warning(boolean buy, int offerPrice, int marketPrice, int gapGp, double gapPct) {
            this.buy = buy;
            this.offerPrice = offerPrice;
            this.marketPrice = marketPrice;
            this.gapGp = gapGp;
            this.gapPct = gapPct;
        }

        public String headline() {
            return buy ? "Buy over market" : "Sell under buyers";
        }

        /** Gap in gp and percent, plus the market price it is measured against. */
        public String detail() {
            String pct = String.format("%.1f", gapPct);
            String relation = buy ? "over" : "under";
            return GP.format(gapGp) + " gp (" + pct + "%) " + relation + " " + GP.format(marketPrice);
        }
    }

    /**
     * After-tax market margin is too thin to flip. Same skip FlipEngine uses:
     * {@code margin = sell - buy - tax(sell)}, then drop the item when
     * {@code margin <= 0} or {@code margin < minMargin} or {@code marginPct < minRoi}
     * ({@code marginPct = margin * 100 / buy}). Thresholds are the user's flip
     * config (plugin defaults 10 gp and 0.3%), not new numbers.
     *
     * Buy setup only. A sell doesn't choose to enter a thin market.
     */
    public static final class ThinMargin {
        public final long marginGp;
        public final double marginPct;

        ThinMargin(long marginGp, double marginPct) {
            this.marginGp = marginGp;
            this.marginPct = marginPct;
        }

        public String headline() { return "Margin too thin to flip"; }

        /** After-tax margin in gp and percent. */
        public String detail() {
            return GP.format(marginGp) + " gp (" + String.format("%.1f", marginPct) + "%) after tax";
        }
    }

    /** Same rule as {@code com.gecopilot.engine.GeTax}: 2% floored, cap 5M, exempt under 50 gp. */
    static long tax(int price) {
        if (price < 50) return 0;
        return Math.min((long) Math.floor(price * 0.02), 5_000_000L);
    }

    public static ThinMargin evaluateMargin(boolean buy, int marketBuy, int marketSell, long minMargin, double minRoi) {
        if (!buy || marketBuy <= 0 || marketSell <= 0) return null;
        long margin = (long) marketSell - marketBuy - tax(marketSell);
        double marginPct = margin * 100.0 / marketBuy;
        if (margin > 0 && margin >= minMargin && marginPct >= minRoi) return null;
        return new ThinMargin(margin, marginPct);
    }

    public static Warning evaluate(boolean buy, int offerPrice, int marketLow, int marketHigh) {
        if (offerPrice <= 0) return null;
        if (!buy) {
            if (marketLow <= 0 || offerPrice >= marketLow) return null;
            int gap = marketLow - offerPrice;
            return new Warning(false, offerPrice, marketLow, gap, 100.0 * gap / marketLow);
        }
        if (marketHigh <= 0 || offerPrice <= marketHigh) return null;
        int gap = offerPrice - marketHigh;
        return new Warning(true, offerPrice, marketHigh, gap, 100.0 * gap / marketHigh);
    }
}

package com.gecopilot.client.ui;

/**
 * Preview → account prompt (copy A). Hidden on first paint.
 *
 * The preview list is read-only: no watch star and no offer view. The earliest
 * meaningful action is choosing a flip card. That choice reveals the prompt once
 * per session. "Continue without saving" dismisses it for the rest of the session.
 */
public final class PreviewSavePrompt {
    public enum Phase { HIDDEN, ASK, FIELDS, DISMISSED }

    private Phase phase = Phase.HIDDEN;
    private int pickId;

    public Phase phase() { return phase; }

    /** Item the player chose when the prompt opened. 0 if none. */
    public int pickId() { return pickId; }

    /** @return true only on the transition that first reveals the prompt */
    public boolean onFlipChosen(int itemId) {
        if (itemId <= 0 || phase != Phase.HIDDEN) return false;
        pickId = itemId;
        phase = Phase.ASK;
        return true;
    }

    public void saveClicked() {
        if (phase == Phase.ASK) phase = Phase.FIELDS;
    }

    public void continueWithoutSaving() {
        phase = Phase.DISMISSED;
        pickId = 0;
    }

    public void reset() {
        phase = Phase.HIDDEN;
        pickId = 0;
    }
}

package com.gecopilot.client.ui;

/**
 * The quiet "Updating… / Updated just now / Last updated Nm ago" cue in the panel header. Pure, so
 * the wording is testable without Swing.
 */
public final class RefreshStatus {
    public enum State { IDLE, UPDATING, OK, FAILED }

    /** Widest text the label can show; every state must fit on the header row. */
    static final String WIDEST = "Last updated 59m ago";

    private RefreshStatus() {}

    /**
     * @param lastOkMs wall-clock time of the last refresh that landed, or 0 if none has this session
     */
    public static String text(State state, long lastOkMs, long nowMs) {
        switch (state) {
            case UPDATING: return "Updating\u2026";
            case OK: return "Updated just now";
            case FAILED: return lastOkMs > 0 ? "Last updated " + ago(nowMs - lastOkMs) + " ago" : "Not updated yet";
            default: return " "; // keeps the row's height before the first refresh
        }
    }

    /** Whole minutes (at least 1), then hours, then days. */
    static String ago(long ms) {
        long min = Math.max(1, ms / 60_000L);
        if (min < 60) return min + "m";
        long h = min / 60;
        if (h < 24) return h + "h";
        return (h / 24) + "d";
    }
}

package com.gecopilot.client.ui;

import java.util.Locale;

/**
 * First-session next step. Stages only move forward: open the GE, place or view an offer,
 * wait for the fill, then the first live trade. {@code offersKnown} false (GE not opened yet,
 * or an older client that does not report it) stays on the open-GE step unless the server
 * has already recorded an offer or a live trade.
 */
public final class SessionGuide {
    public enum Stage { OPEN_GE, PLACE_OFFER, WAIT_FILL, DONE }

    private SessionGuide() {}

    public static Stage stage(boolean offersKnown, boolean offersSeen, boolean firstLiveTrade) {
        if (firstLiveTrade) return Stage.DONE;
        if (offersSeen) return Stage.WAIT_FILL;
        if (offersKnown) return Stage.PLACE_OFFER;
        return Stage.OPEN_GE;
    }

    /** A failed sync must not walk the session backwards. */
    public static Stage advance(Stage from, Stage to) {
        if (to == null) return from == null ? Stage.OPEN_GE : from;
        if (from == null) return to;
        return to.ordinal() < from.ordinal() ? from : to;
    }

    /** Persistent next action. Null once the guide is finished. */
    public static String banner(Stage stage, String flipName, int placeBuy) {
        if (stage == null || stage == Stage.DONE) return null;
        if (stage == Stage.OPEN_GE) return "Next: open the Grand Exchange.";
        if (stage == Stage.PLACE_OFFER) {
            if (flipName != null && !flipName.isEmpty() && placeBuy > 0)
                return "Next: in the GE, buy " + flipName + " @ " + String.format(Locale.US, "%,d", placeBuy) + ".";
            return "Next: place or view an offer in the GE.";
        }
        return "Offer synced. Sell it when it fills — see Positions.";
    }

    /** Spoken once when the stage advances. Null on the first observation. */
    public static String transitionToast(Stage from, Stage to) {
        if (to == null || from == null || to == from || to.ordinal() < from.ordinal()) return null;
        if (to == Stage.DONE) return "First trade recorded.";
        if (to == Stage.WAIT_FILL) return "Offer synced. Check Positions.";
        if (to == Stage.PLACE_OFFER) return "GE is open. Place or view an offer.";
        return null;
    }

    public static String emptyFlips(Stage stage) {
        if (stage == Stage.OPEN_GE) return "No flips yet. Open the Grand Exchange.";
        if (stage == Stage.PLACE_OFFER) return "No flips match. Place or view any GE offer.";
        if (stage == Stage.WAIT_FILL) return "No other flips right now. Your offer is on Positions.";
        return "No flips right now.";
    }

    public static String emptyPlan(Stage stage) {
        if (stage == Stage.OPEN_GE) return "No plan yet. Open the Grand Exchange.";
        if (stage == Stage.PLACE_OFFER) return "Nothing to place. View an offer, or ease filters.";
        if (stage == Stage.WAIT_FILL) return "Nothing to place until a slot frees.";
        return "Nothing to place right now.";
    }

    public static String emptyPositions(Stage stage) {
        if (stage == Stage.OPEN_GE) return "No offers yet. Open the Grand Exchange.";
        if (stage == Stage.PLACE_OFFER) return "No offer yet. Buy the top Finder pick in the GE.";
        if (stage == Stage.WAIT_FILL) return "No open offers. Sell the fill to finish the flip.";
        return "No open offers.";
    }
}

package com.gecopilot.client.ui;

import com.gecopilot.client.api.StatusMonitor;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;

/**
 * Service-status banner at the top of a panel card. Plain text only (a JTextArea, never HTML), so a
 * server message can't inject markup. The link is copied to the clipboard rather than opened:
 * LinkBrowser.open is a restricted Plugin Hub API (see 5530c12). EDT only.
 */
final class StatusBanner extends JPanel {
    static final String COPY_LINK = "Copy link for details";
    /** Sidebar width less the card margin, the accent bar and the banner padding. */
    private static final int TEXT_WIDTH = net.runelite.client.ui.PluginPanel.PANEL_WIDTH - 16 - 3 - 16;

    private final JTextArea text = new JTextArea();
    private final JLabel since = new JLabel();
    private final JLabel link = new JLabel(COPY_LINK);
    private String linkUrl;

    StatusBanner() {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setAlignmentX(Component.LEFT_ALIGNMENT);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, Short.MAX_VALUE));
        text.setEditable(false); text.setFocusable(false);
        text.setLineWrap(true); text.setWrapStyleWord(true); text.setOpaque(false); text.setBorder(null);
        text.setFont(FontManager.getRunescapeSmallFont());
        text.setForeground(Color.WHITE);
        text.setAlignmentX(Component.LEFT_ALIGNMENT);
        // A wrapping JTextArea sizes its height from its current width, which is 0 before the first
        // layout; seed it with the sidebar's text width so the first paint wraps instead of clipping.
        text.setSize(new Dimension(TEXT_WIDTH, Short.MAX_VALUE));
        since.setFont(FontManager.getRunescapeSmallFont());
        since.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        since.setAlignmentX(Component.LEFT_ALIGNMENT);
        since.setBorder(BorderFactory.createEmptyBorder(2, 0, 0, 0));
        link.setFont(FontManager.getRunescapeSmallFont());
        link.setForeground(new Color(0x4f, 0xc3, 0xf7));
        link.setAlignmentX(Component.LEFT_ALIGNMENT);
        link.setBorder(BorderFactory.createEmptyBorder(2, 0, 0, 0));
        link.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        link.addMouseListener(new MouseAdapter() {
            @Override public void mousePressed(MouseEvent e) {
                if (linkUrl != null) CloudPanel.copyLinkToClipboard(linkUrl, link, linkLabel(linkUrl));
            }
        });
        add(text);
        add(since);
        add(link);
        setVisible(false);
    }

    void show(StatusMonitor.Banner b) {
        if (b == null) { setVisible(false); linkUrl = null; return; }
        Color bg, accent;
        switch (b.level) {
            case INFO: bg = new Color(0x1a, 0x22, 0x2e); accent = new Color(0x4f, 0xc3, 0xf7); break;
            case WARNING: bg = new Color(0x3a, 0x30, 0x10); accent = ColorScheme.BRAND_ORANGE; break;
            default: bg = new Color(0x4a, 0x18, 0x18); accent = ColorScheme.PROGRESS_ERROR_COLOR; break;
        }
        setBackground(bg);
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
            BorderFactory.createEmptyBorder(6, 8, 6, 8)));
        text.setText(b.text);
        if (text.getWidth() <= 0) text.setSize(new Dimension(TEXT_WIDTH, Short.MAX_VALUE));
        String s = sinceText(b.since, System.currentTimeMillis());
        since.setText(s == null ? "" : s);
        since.setVisible(s != null);
        linkUrl = b.link;
        link.setVisible(b.link != null);
        link.setText(b.link == null ? COPY_LINK : linkLabel(b.link));
        link.setToolTipText(b.link);
        setVisible(true);
        revalidate();
        repaint();
    }

    String shownText() { return isVisible() ? text.getText() : null; }
    String shownLink() { return isVisible() && link.isVisible() ? link.getText() : null; }

    static final int LINK_CHARS = 32;

    /** "Copy link: meetcoffer.com/status", so players see where it goes. Host + path, shortened. */
    static String linkLabel(String url) {
        String shown = url.replaceFirst("(?i)^https://", "");
        int q = shown.indexOf('?');
        if (q >= 0) shown = shown.substring(0, q);
        int h = shown.indexOf('#');
        if (h >= 0) shown = shown.substring(0, h);
        if (shown.endsWith("/")) shown = shown.substring(0, shown.length() - 1);
        if (shown.length() > LINK_CHARS) shown = shown.substring(0, LINK_CHARS - 1) + "\u2026";
        return "Copy link: " + shown;
    }

    /**
     * "Since 12m ago" / "Since 3h ago" / "Since 2d ago": relative, so no time zone to explain. Same
     * wording as the header's refresh cue. A time in the future (clock skew) reads as 1m. Null without
     * a parseable time.
     */
    static String sinceText(String iso, long nowMs) {
        if (iso == null) return null;
        try { return "Since " + RefreshStatus.ago(Math.max(0, nowMs - Instant.parse(iso).toEpochMilli())) + " ago"; }
        catch (RuntimeException e) { return null; }
    }
}

package com.gecopilot.client;

import org.junit.Test;

import static org.junit.Assert.*;

/** The server's notice text can't inject chat tags: ChatMessageBuilder.append(String) escapes it. */
public class ChatNoticeTest {
    @Test public void angleBracketsAreEscaped() {
        String line = GeCopilotCloudPlugin.chatLine("<col=ff0000>Free gp</col> <img=1>");
        assertFalse(line, line.contains("<col=ff0000>Free"));
        assertFalse(line, line.contains("<img=1>"));
