    @Test public void parsesSparklineDroppingZeroPointsAndCappingTo24() {
        StringBuilder wiki = new StringBuilder("[");
        for (int i = 0; i < 30; i++) {
            if (i > 0) wiki.append(",");
            wiki.append("{\"ts\":").append(i).append(",\"high\":100,\"low\":80}");
