package com.gecopilot.client.api;

import org.junit.Before;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;

import static org.junit.Assert.*;

/** Poll cadence and refresh depth by panel visibility. */
public class PollCycleTest {
    private final AtomicLong clock = new AtomicLong(1_000_000L);
    private final AtomicBoolean minimised = new AtomicBoolean(false);
    private final List<String> calls = Collections.synchronizedList(new ArrayList<>());
    private final List<Dashboard> rendered = new ArrayList<>();
    private boolean ready = true;
    private boolean serverUp = true;
    private boolean throwOnSync = false;
    private PollPolicy policy;
    private PollCycle cycle;

    private final class Recorder implements PollCycle.Steps {
        @Override public boolean ready() { return ready; }
        @Override public void beforeSync() { calls.add("before"); }
        @Override public void flushQueues() { calls.add("flush"); }
        @Override public SyncResult sync() {
            calls.add("flips");
            if (throwOnSync) throw new IllegalStateException("boom");
            SyncResult r = new SyncResult();
            if (serverUp) r.tier = "premium";
            return r;
        }
        @Override public Dashboard dashboard() { calls.add("dashboard"); return serverUp ? new Dashboard() : null; }
        @Override public void render(SyncResult s, Dashboard d) { calls.add("render"); rendered.add(d); }
        @Override public void logPlan(SyncResult s) { calls.add("planShown"); }
        @Override public void nudge(SyncResult s) { calls.add("nudge"); }
        @Override public void done(boolean ok) { calls.add(ok ? "ok" : "failed"); }
    }

    @Before public void up() {
        policy = new PollPolicy(clock::get, minimised::get);
        cycle = new PollCycle(policy, new Recorder());
    }

    /** Simulate the fixed-delay timer for {@code minutes}, one tick a minute; returns /api/flips posts. */
    private int runTicks(int minutes) {
        int before = count("flips");
        for (int i = 0; i < minutes; i++) {
            clock.addAndGet(PollPolicy.TICK_MS);
            cycle.onTick();
        }
        return count("flips") - before;
    }

    private int count(String what) {
        synchronized (calls) { return (int) calls.stream().filter(what::equals).count(); }
    }

    @Test public void visiblePanelPollsEveryTick() {
        policy.setPanelVisible(true);
        assertEquals(30, runTicks(30));
        assertEquals(30, count("dashboard"));
        assertEquals(30, count("planShown"));
    }

    @Test public void hiddenPanelPollsEveryTenMinutes() {
        cycle.onTick();               // startup tick: first sync of the session always goes out
        assertEquals(1, count("flips"));
        assertEquals(0, runTicks(9));  // 1..9 min since the last sync
        assertEquals(1, runTicks(1));  // 10 min
        assertEquals(3, runTicks(30));
    }

    @Test public void hiddenCadenceToleratesTimerDrift() {
        cycle.onTick();
        // Fixed-delay ticks land slightly under a minute apart relative to the stamped sync.
        for (int i = 0; i < 10; i++) { clock.addAndGet(PollPolicy.TICK_MS - 150); cycle.onTick(); }
        assertEquals(2, count("flips"));
    }

    @Test public void hiddenPollIsLight() {
        cycle.onTick();
        assertEquals(List.of("before", "flush", "flips", "render", "nudge", "ok"), calls);
        assertNull("no dashboard while hidden; panel keeps its last one", rendered.get(0));
        assertEquals(0, count("dashboard"));
        assertEquals(0, count("planShown"));
    }

    @Test public void geEventRefreshFollowsVisibility() {
        cycle.refresh();
        assertEquals(1, count("flips"));
        assertEquals(1, count("flush"));
        assertEquals(1, count("nudge"));
        assertEquals(0, count("dashboard"));
        assertEquals(0, count("planShown"));
        policy.setPanelVisible(true);
        cycle.refresh();
        assertEquals(1, count("dashboard"));
        assertEquals(1, count("planShown"));
    }

    @Test public void geEventSyncResetsTheHiddenClock() {
        cycle.onTick();
        clock.addAndGet(8 * PollPolicy.TICK_MS);
        cycle.refresh();              // an offer changed 8 min in
        assertEquals(2, count("flips"));
        assertEquals(0, runTicks(9)); // next timer poll is 10 min after that sync, not after the first
        assertEquals(1, runTicks(1));
    }

    @Test public void openingThePanelRefreshesFullyAtOnce() {
        cycle.onTick();
        clock.addAndGet(3 * PollPolicy.TICK_MS);
        policy.setPanelVisible(true);
        cycle.refreshFull();          // what onActivate schedules
        assertEquals(2, count("flips"));
        assertEquals(1, count("dashboard"));
        assertEquals(1, count("planShown"));
        assertNotNull(rendered.get(1));
        assertEquals("visible again: back to every tick", 1, runTicks(1));
    }

    @Test public void closingThePanelReturnsToHiddenCadence() {
        policy.setPanelVisible(true);
        runTicks(3);
        policy.setPanelVisible(false);
        assertEquals(0, runTicks(9));
        assertEquals(1, runTicks(1));
    }

    @Test public void minimisedClientCountsAsHidden() {
        policy.setPanelVisible(true);
        minimised.set(true);
        assertFalse(policy.visible());
        cycle.onTick();
        assertEquals(0, count("dashboard"));
        assertEquals(0, runTicks(9));
        minimised.set(false);
        assertEquals(1, runTicks(1));
        assertEquals(1, count("dashboard"));
    }

    @Test public void throwingMinimisedProbeFallsBackToPanelState() {
        PollPolicy p = new PollPolicy(clock::get, () -> { throw new IllegalStateException("no frame"); });
        p.setPanelVisible(true);
        assertTrue(p.visible());
    }

    @Test public void signedOutDoesNothingAndKeepsTheFirstSyncDue() {
        ready = false;
        runTicks(5);
        assertEquals(0, count("flips"));
        ready = true;
        assertEquals("first signed-in tick syncs right away", 1, runTicks(1));
    }

    @Test public void hiddenIntervalStaysInsideServerWindows() {
        // Over Neon's 5-min autosuspend + 30s pool idle timeout, under the 15-min crowd-count window
        // even with a full tick of lag.
        assertTrue(PollPolicy.HIDDEN_INTERVAL_MS > 5 * 60_000L + 30_000L);
        assertTrue(PollPolicy.HIDDEN_INTERVAL_MS + PollPolicy.TICK_MS < 15 * 60_000L);
    }

    @Test public void reportsSuccessWhenTheServerAnswers() {
        policy.setPanelVisible(true);
        cycle.refreshFull();
        assertEquals(1, count("ok"));
        assertEquals(0, count("failed"));
    }

    @Test public void reportsFailureWhenSyncOrDashboardFails() {
        serverUp = false;
        cycle.refreshFull();
        assertEquals(1, count("failed"));
        cycle.refresh();              // light refresh, sync empty
        assertEquals(2, count("failed"));
    }

    @Test public void reportsFailureEvenWhenAStepThrows() {
        throwOnSync = true;
        try { cycle.refreshFull(); fail("expected the exception to propagate"); }
        catch (IllegalStateException expected) { }
        assertEquals("header must not stick on Updating", 1, count("failed"));
    }

    @Test public void signedOutReportsFailureSoTheCueCannotStick() {
        ready = false;
        cycle.refreshFull();
        assertEquals(1, count("failed"));
        assertEquals(0, count("flips"));
    }

    @Test public void restoringAMinimisedClientWithThePanelOpenRefreshesAtOnce() {
        policy.setPanelVisible(true);
        assertFalse("minimising needs no refresh", policy.onWindowState(true));
        assertTrue("restored with the panel on screen", policy.onWindowState(false));
        assertFalse("a second restore event is not a new restore", policy.onWindowState(false));
    }

    @Test public void restoringWithThePanelClosedWaitsForTheHiddenCadence() {
        policy.onWindowState(true);
        assertFalse(policy.onWindowState(false));
    }

    @Test public void maximiseOrOtherStateChangesAreNotRestores() {
        policy.setPanelVisible(true);
        assertFalse(policy.onWindowState(false));
        assertFalse(policy.onWindowState(false));
    }
}

package com.gecopilot.client.api;

import org.junit.Test;

import static org.junit.Assert.*;

/** The GE overlay quote fetch must not retry every game tick. */
public class QuoteBackoffTest {
    private static final long TICK = 600;

    @Test public void oneRequestInFlightPerItem() {
        QuoteBackoff b = new QuoteBackoff();
        assertTrue(b.tryStart(4151, 0));
        for (int t = 1; t <= 100; t++) assertFalse("tick " + t, b.tryStart(4151, t * TICK));
    }

    @Test public void failuresBackOffExponentiallyToTheCap() {
        assertEquals(1_000, QuoteBackoff.delayMs(1));
        assertEquals(2_000, QuoteBackoff.delayMs(2));
        assertEquals(4_000, QuoteBackoff.delayMs(3));
        assertEquals(16_000, QuoteBackoff.delayMs(5));
        assertEquals(30_000, QuoteBackoff.delayMs(6));
        assertEquals(30_000, QuoteBackoff.delayMs(500));
    }

    @Test public void failedItemWaitsBeforeRetrying() {
        QuoteBackoff b = new QuoteBackoff();
        assertTrue(b.tryStart(4151, 0));
        b.failed(4151, 0);
        assertFalse(b.tryStart(4151, 999));
        assertTrue(b.tryStart(4151, 1_000));
        b.failed(4151, 1_000);
        assertFalse(b.tryStart(4151, 2_999));
        assertTrue(b.tryStart(4151, 3_000));
    }

    @Test public void tenMinutesOfFailuresIsAFewDozenRequestsNotAThousand() {
        QuoteBackoff b = new QuoteBackoff();
        int requests = 0;
        for (long now = 0; now < 10 * 60_000L; now += TICK) {
            if (b.tryStart(4151, now)) { requests++; b.failed(4151, now); }
        }
        // Old behaviour: a request every 0.6s tick = 1000. Capped at 30s: about 25.
        assertTrue("requests=" + requests, requests <= 30);
        assertTrue("still retries", requests >= 15);
    }

    @Test public void successClearsTheBackoff() {
        QuoteBackoff b = new QuoteBackoff();
        b.tryStart(4151, 0);
        b.failed(4151, 0);
        b.tryStart(4151, 1_000);
        b.failed(4151, 1_000);
        assertTrue(b.tryStart(4151, 3_000));
        assertTrue(b.succeeded(4151));
        assertTrue(b.tryStart(4151, 3_001));
    }

    @Test public void newItemStartsFreshAndStaleResultsAreIgnored() {
        QuoteBackoff b = new QuoteBackoff();
        assertTrue(b.tryStart(4151, 0));
        assertTrue("switching item does not wait on the old request", b.tryStart(11802, TICK));
        assertFalse("old item's late answer must not land", b.succeeded(4151));
        b.failed(4151, TICK);         // ignored too
        assertFalse(b.tryStart(11802, 2 * TICK)); // new item still in flight
        assertTrue(b.succeeded(11802));
    }

    @Test public void resetOnLeavingTheGeScreen() {
        QuoteBackoff b = new QuoteBackoff();
        b.tryStart(4151, 0);
        b.failed(4151, 0);
        b.reset();
        assertTrue(b.tryStart(4151, 1));
    }

    @Test public void attemptClearsInFlightEvenWhenTheFetchThrowsAnError() {
        QuoteBackoff b = new QuoteBackoff();
        assertTrue(b.tryStart(4151, 0));
        try {
            b.attempt(4151, () -> { throw new AssertionError("not an Exception"); }, () -> 0L);
            fail("expected the error to propagate");
        } catch (AssertionError expected) { }
        assertFalse("backs off like any failure", b.tryStart(4151, 999));
        assertTrue("not stuck in flight", b.tryStart(4151, 1_000));
    }

    @Test public void attemptReturnsTheQuoteOnSuccess() {
        QuoteBackoff b = new QuoteBackoff();
        assertTrue(b.tryStart(4151, 0));
        assertEquals("q", b.attempt(4151, () -> "q", () -> 0L));
        assertTrue(b.tryStart(4151, 1));
    }

    @Test public void attemptTreatsNullAsAFailure() {
        QuoteBackoff b = new QuoteBackoff();
        assertTrue(b.tryStart(4151, 0));
        assertNull(b.attempt(4151, () -> null, () -> 0L));
        assertFalse(b.tryStart(4151, 500));
        assertTrue(b.tryStart(4151, 1_000));
    }

    @Test public void attemptDropsALateAnswerForAnItemThePlayerLeft() {
        QuoteBackoff b = new QuoteBackoff();
        assertTrue(b.tryStart(4151, 0));
        assertTrue(b.tryStart(11802, 600));
        assertNull(b.attempt(4151, () -> "stale", () -> 600L));
        assertFalse("new item still in flight", b.tryStart(11802, 1_200));
    }
}

package com.gecopilot.client.api;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;

import static org.junit.Assert.*;

public class StatusMonitorTest {
    private final AtomicLong now = new AtomicLong(1_000_000L);
    private final PollPolicy policy = new PollPolicy(now::get, () -> false);
    private final StatusMonitor m = new StatusMonitor(policy, now::get);

    { policy.setPanelVisible(true); }

    private static ServiceStatusDto status(String level, String message, Boolean db) {
        ServiceStatusDto s = new ServiceStatusDto();
        s.level = level;
        s.message = message;
        s.db = db;
        return s;
    }

    private StatusMonitor.Update check(ServiceStatusDto s) {
        assertTrue("check should be due", m.tryStart());
        return m.attempt(() -> s);
    }

    private static final long MIN = 60_000L;

    @Test public void healthyMeansNoBannerAndFiveMinuteChecks() {
        StatusMonitor.Update u = check(status(null, null, true));
        assertNull(u.banner);
        assertFalse(m.degraded());
        assertNull(u.chatNotice);
        now.addAndGet(4 * MIN);
        assertFalse(m.due());
        now.addAndGet(MIN);
        assertTrue(m.due());
    }

    @Test public void explicitMessageWinsOverAutoDetect() {
        ServiceStatusDto s = status("warning", "Fills may lag while we upgrade the database.", false);
        s.link = "https://meetcoffer.com/status";
        s.since = "2026-10-19T14:00:00Z";
        StatusMonitor.Banner b = check(s).banner;
        assertEquals(StatusMonitor.Level.WARNING, b.level);
        assertEquals("Fills may lag while we upgrade the database.", b.text);
        assertEquals("https://meetcoffer.com/status", b.link);
        assertEquals("2026-10-19T14:00:00Z", b.since);
        assertFalse(b.auto);
        assertTrue("db:false still backs off", m.degraded());
    }

    @Test public void autoDetectOutageWhenUnreachableOrDbDown() {
        StatusMonitor.Banner down = check(status(null, null, false)).banner;
        assertEquals(StatusMonitor.Level.OUTAGE, down.level);
        assertEquals(StatusMonitor.DEFAULT_OUTAGE, down.text);
        assertTrue(down.auto);

        StatusMonitor fresh = new StatusMonitor(policy, now::get);
        assertTrue(fresh.tryStart());
        StatusMonitor.Banner unreachable = fresh.attempt(() -> null).banner;
        assertEquals(down, unreachable);
        assertTrue(fresh.degraded());

        StatusMonitor thrown = new StatusMonitor(policy, now::get);
        assertTrue(thrown.tryStart());
        assertEquals(down, thrown.attempt(() -> { throw new IllegalStateException("timeout"); }).banner);
    }

    @Test public void unknownDbAndOldServerShowNothing() {
        assertNull(check(status(null, null, null)).banner);   // nothing has tried the DB yet
        now.addAndGet(5 * MIN);
        assertNull(check(new ServiceStatusDto()).banner);     // 404 from a server without /api/status
        assertFalse(m.degraded());
    }

    @Test public void levelWithoutMessage() {
        assertEquals(StatusMonitor.DEFAULT_OUTAGE, check(status("outage", "  ", true)).banner.text);
        assertTrue("an announced outage backs off too", m.degraded());
        StatusMonitor other = new StatusMonitor(policy, now::get);
        assertTrue(other.tryStart());
        assertNull("info with nothing to say shows nothing", other.attempt(() -> status("info", null, true)).banner);
    }

    @Test public void textIsPlainAndLinksAreHttpsOnly() {
        ServiceStatusDto s = status("info", "a\nb\tc\u0007d", true);
        s.link = "http://meetcoffer.com";
        StatusMonitor.Banner b = check(s).banner;
        assertEquals("a b c d", b.text);
        assertNull(b.link);
        assertNull(StatusMonitor.httpsOrNull("javascript:alert(1)"));
        assertNull(StatusMonitor.httpsOrNull("https://u:p@evil.example"));
        assertEquals("https://meetcoffer.com/x", StatusMonitor.httpsOrNull("https://meetcoffer.com/x"));
        assertEquals(StatusMonitor.MAX_TEXT, StatusMonitor.clean("y".repeat(900)).length());
    }

    @Test public void outageBacksOffOneTwoFiveTenFifteenThenResets() {
        List<Long> waits = new ArrayList<>();
        for (int i = 0; i < 7; i++) {
            check(null);
            long waited = 0;
            while (!m.due()) { now.addAndGet(1_000L); waited += 1_000L; }
            waits.add(Math.round(waited / (double) MIN));
        }
        assertEquals(List.of(1L, 2L, 5L, 10L, 15L, 15L, 15L), waits);

        StatusMonitor.Update back = check(status(null, null, true));
        assertTrue(back.recovered);
        assertNull("banner clears on recovery", back.banner);
        assertTrue(back.changed);
        assertFalse(m.degraded());
        assertEquals(StatusMonitor.HEALTHY_INTERVAL_MS, m.intervalMs());

        now.addAndGet(StatusMonitor.HEALTHY_INTERVAL_MS);
        check(null);
        assertEquals("a new outage starts the schedule again", MIN, m.intervalMs());
    }

    @Test public void hiddenPanelNeverChecksFasterThanTheHiddenPoll() {
        check(null);
        policy.setPanelVisible(false);
        assertEquals(PollPolicy.HIDDEN_INTERVAL_MS, m.intervalMs());
        policy.setPanelVisible(true);
        assertEquals(MIN, m.intervalMs());
        StatusMonitor minimised = new StatusMonitor(new PollPolicy(now::get, () -> true), now::get);
        assertEquals(PollPolicy.HIDDEN_INTERVAL_MS, minimised.intervalMs());
    }

    @Test public void chatNoticeOncePerDistinctBannerPerSession() {
        List<String> notices = new ArrayList<>();
        ServiceStatusDto a = status("warning", "Maintenance at 18:00 UTC", true);
        ServiceStatusDto b = status("outage", "Database upgrade in progress", true);
        ServiceStatusDto[] seq = {a, a, null, a, b, b, status(null, null, true), b, a};
        for (ServiceStatusDto s : seq) {
            StatusMonitor.Update u = check(s);
            if (u.chatNotice != null) notices.add(u.chatNotice);
            now.addAndGet(20 * MIN);
        }
        assertEquals(List.of("Maintenance at 18:00 UTC", StatusMonitor.DEFAULT_OUTAGE, "Database upgrade in progress"), notices);
    }

    @Test public void sameBannerIsNotReRendered() {
        assertTrue(check(status("info", "Hello", true)).changed);
        now.addAndGet(5 * MIN);
        assertFalse(check(status("info", "Hello", true)).changed);
        now.addAndGet(5 * MIN);
        assertTrue(check(status("info", "Hello again", true)).changed);
    }

    @Test public void oneCheckInFlightAndAnErrorCannotWedgeIt() {
        assertTrue(m.tryStart());
        assertFalse("second check while one is in flight", m.tryStart());
        try {
            m.attempt(() -> { throw new AssertionError("boom"); });
            fail();
        } catch (AssertionError expected) { }
        assertTrue("recorded as unreachable", m.degraded());
        now.addAndGet(MIN);
        assertTrue("next check is allowed after the backoff", m.tryStart());
    }

    /** Records which requests a run of timer ticks makes. */
    private List<String> runTicks(int ticks, java.util.function.Supplier<ServiceStatusDto> server) {
        List<String> calls = new ArrayList<>();
        for (int i = 0; i < ticks; i++) {
            m.tick(() -> calls.add("tick"), () -> calls.add("probe-sync"),
                () -> { calls.add("status"); return server.get(); }, u -> { });
            now.addAndGet(PollPolicy.TICK_MS);
        }
        return calls;
    }

    @Test public void healthyTicksPollEveryMinuteAndCheckStatusEveryFive() {
        List<String> calls = runTicks(10, () -> status(null, null, true));
        assertEquals(10, calls.stream().filter("tick"::equals).count());
        assertEquals(2, calls.stream().filter("status"::equals).count()); // t=0 and t=5min
        assertEquals(0, calls.stream().filter("probe-sync"::equals).count());
        assertEquals("regular poll goes first, so its sync refreshes the server's db flag", "tick", calls.get(0));
    }

    @Test public void outagePausesTheRegularPollAndProbesOncePerStep() {
        // 0: healthy tick, check -> down. Then checks due after 1, 2, 5, 10, 15 min of waiting.
        List<String> calls = runTicks(60, () -> null);
        assertEquals("only the first tick before the outage was known", 1, calls.stream().filter("tick"::equals).count());
        long checks = calls.stream().filter("status"::equals).count();
        assertEquals("checks at minutes 0, 1, 3, 8, 18, 33, 48", 7, checks);
        assertEquals(checks - 1, calls.stream().filter("probe-sync"::equals).count());
        int i = calls.indexOf("probe-sync");
        assertEquals("probe sync runs right before the status check", "status", calls.get(i + 1));
    }

    @Test public void recoveryResumesTheRegularPoll() {
        boolean[] up = {false};
        List<String> calls = runTicks(3, () -> up[0] ? status(null, null, true) : null);
        up[0] = true;
        calls.addAll(runTicks(4, () -> status(null, null, true)));
        // t0 tick + check (down); t1 probe + check (down); t2 waiting; t3 probe + check (up); t4.. regular
        assertEquals(List.of("tick", "status", "probe-sync", "status", "probe-sync", "status", "tick", "tick", "tick"), calls);
    }

    @Test public void ownFailingCallsFillInAnUnknownDb() {
        assertEquals(Boolean.FALSE, StatusMonitor.withOwnCalls(status(null, null, null), true).db);
        assertNull(StatusMonitor.withOwnCalls(status(null, null, null), false).db);
        assertEquals("the server's answer wins", Boolean.TRUE, StatusMonitor.withOwnCalls(status(null, null, true), true).db);
        assertNull("unreachable stays unreachable", StatusMonitor.withOwnCalls(null, true));
        StatusMonitor.Banner b = check(StatusMonitor.withOwnCalls(new ServiceStatusDto(), true)).banner;
        assertEquals(StatusMonitor.DEFAULT_OUTAGE, b.text);
        assertTrue(b.auto);
    }

    @Test public void dbFalseAloneKeepsTheRegularPollRunning() {
        // The server answers; only its passive db flag is false. The plugin's own syncs are what
        // reconnect and clear it, so they must keep running.
        List<String> calls = runTicks(10, () -> status(null, null, false));
        assertEquals(10, calls.stream().filter("tick"::equals).count());
        assertEquals(0, calls.stream().filter("probe-sync"::equals).count());
        assertEquals("status checks still back off: minutes 0, 1, 3, 8", 4, calls.stream().filter("status"::equals).count());
        assertTrue(m.degraded());
        assertFalse(m.pausesRegularPoll());
        assertEquals(StatusMonitor.DEFAULT_OUTAGE, m.banner().text);
    }

    @Test public void dbFlagClearingClearsTheBanner() {
        runTicks(2, () -> status(null, null, false));
        assertNotNull(m.banner());
        List<String> calls = runTicks(2, () -> status(null, null, true));
        assertTrue(calls.contains("status"));
        assertNull(m.banner());
        assertFalse(m.degraded());
    }

    @Test public void unreachableOrAnnouncedOutagePausesTheRegularPoll() {
        check(null);
        assertTrue(m.pausesRegularPoll());
        StatusMonitor other = new StatusMonitor(policy, now::get);
        assertTrue(other.tryStart());
        other.attempt(() -> status("outage", "Maintenance", true));
        assertTrue(other.pausesRegularPoll());
        StatusMonitor warn = new StatusMonitor(policy, now::get);
        assertTrue(warn.tryStart());
        warn.attempt(() -> status("warning", "Slow", true));
        assertFalse(warn.pausesRegularPoll());
    }

    @Test public void cleanDropsBidiAndZeroWidthCharacters() {
        assertEquals("Hello world", StatusMonitor.clean("Hel\u200Blo \u202Eworld\u202C\uFEFF"));
        assertEquals("ab", StatusMonitor.clean("a\u2066\u200Db"));
    }
}

package com.gecopilot.client.api;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;

import static org.junit.Assert.*;

public class TimeseriesCacheTest {
    /** Loads started by the cache; the test completes them like OkHttp's dispatcher would. */
    private final List<TimeseriesCache.Callback> pending = new ArrayList<>();
    private final List<Integer> requestedIds = new ArrayList<>();
    private final AtomicLong now = new AtomicLong(1_000_000L);

    private TimeseriesCache cache() {
        return new TimeseriesCache((id, step, cb) -> { requestedIds.add(id); pending.add(cb); }, now::get);
    }

    private void succeedAll() {
        List<TimeseriesCache.Callback> copy = new ArrayList<>(pending);
        pending.clear();
        for (int i = 0; i < copy.size(); i++) copy.get(i).onSuccess(Collections.singletonList(point(requestedIds.get(i))));
        requestedIds.clear();
    }

    private void failAll() {
        List<TimeseriesCache.Callback> copy = new ArrayList<>(pending);
        pending.clear();
        requestedIds.clear();
        for (TimeseriesCache.Callback cb : copy) cb.onFailure(new java.io.IOException("down"));
    }

    @Test public void firstGetReturnsNullAndStartsOneLoad() {
        TimeseriesCache c = cache();
        assertNull(c.get(4151, "5m"));
        assertNull(c.get(4151, "5m"));
        assertNull(c.get(4151, "5m"));
        assertEquals("concurrent gets share one in-flight load", 1, pending.size());
        assertTrue(c.isLoading(4151, "5m"));
        succeedAll();
        assertFalse(c.isLoading(4151, "5m"));
        TimeseriesCache.Series s = c.get(4151, "5m");
        assertNotNull("callback populated the cache", s);
        assertFalse(s.failed);
        assertEquals(4152L, s.points.get(0).high);
        assertTrue(pending.isEmpty());
    }

    @Test public void keyIsItemPlusTimestep() {
        TimeseriesCache c = cache();
        c.get(4151, "5m");
        c.get(4151, "1h");
        c.get(11802, "5m");
        assertEquals(3, pending.size());
    }

    @Test public void freshWithinTtlThenReloadsButServesStale() {
        TimeseriesCache c = cache();
        c.get(4151, "5m");
        succeedAll();
        now.addAndGet(TimeseriesCache.TTL_MS - 1);
        assertNotNull(c.get(4151, "5m"));
        assertTrue("still fresh", pending.isEmpty());
        now.addAndGet(2);
        assertNotNull("stale data keeps drawing while the reload runs", c.get(4151, "5m"));
        assertEquals(1, pending.size());
        c.get(4151, "5m");
        assertEquals("no duplicate reload", 1, pending.size());
    }

    @Test public void failureKeepsOldPointsAndBacksOffThirtySeconds() {
        TimeseriesCache c = cache();
        c.get(4151, "5m");
        succeedAll();
        now.addAndGet(TimeseriesCache.TTL_MS);
        c.get(4151, "5m");
        failAll();
        TimeseriesCache.Series s = c.get(4151, "5m");
        assertTrue(s.failed);
        assertEquals("previous points kept", 1, s.points.size());
        assertEquals("data age counts from the last good load", TimeseriesCache.TTL_MS, c.nowMs() - s.dataAtMs);
        assertTrue("no retry inside the backoff", pending.isEmpty());
        now.addAndGet(TimeseriesCache.RETRY_MS - 1);
        c.get(4151, "5m");
        assertTrue(pending.isEmpty());
        now.addAndGet(1);
        c.get(4151, "5m");
        assertEquals("retried after the backoff", 1, pending.size());
    }

    @Test public void firstLoadFailureCachesEmptyFailedSeries() {
        TimeseriesCache c = cache();
        c.get(4151, "5m");
        failAll();
        TimeseriesCache.Series s = c.get(4151, "5m");
        assertNotNull(s);
        assertTrue(s.failed);
        assertTrue(s.points.isEmpty());
        assertFalse(c.isLoading(4151, "5m"));
    }

    @Test public void loaderThrowingSynchronouslyDoesNotWedgeTheKey() {
        TimeseriesCache c = new TimeseriesCache((id, step, cb) -> { throw new IllegalStateException("boom"); }, now::get);
        assertNull(c.get(4151, "5m"));
        assertFalse(c.isLoading(4151, "5m"));
        assertTrue(c.get(4151, "5m").failed);
    }

    @Test public void loaderThrowingAnErrorDoesNotWedgeTheKey() {
        TimeseriesCache c = new TimeseriesCache((id, step, cb) -> { throw new NoClassDefFoundError("boom"); }, now::get);
        assertNull(c.get(4151, "5m"));
        assertFalse(c.isLoading(4151, "5m"));
        assertTrue(c.get(4151, "5m").failed);
    }

    private static SparklineDto.Point point(int id) {
        SparklineDto.Point p = new SparklineDto.Point();
        p.ts = 100; p.high = id + 1; p.low = id;
        return p;
    }
}

package com.gecopilot.client.api;

import com.google.gson.Gson;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.*;

public class WikiTimeseriesTest {
    // Test-only Gson; the plugin hands WikiTimeseries the injected one.
    private static final Gson GSON = new Gson();
    private static final MediaType JSON = MediaType.parse("application/json");
    private static final String SAMPLE = "{\"data\":[{\"timestamp\":1792487400,\"avgHighPrice\":780000,\"avgLowPrice\":770000}]}";

    @Test public void parsesWikiTimeseriesAndNullPrices() {
        WikiTimeseries w = new WikiTimeseries(null, GSON);
        List<SparklineDto.Point> pts = w.parse("{\"data\":["
            + "{\"timestamp\":1792487400,\"avgHighPrice\":780000,\"highPriceVolume\":5,\"avgLowPrice\":770000,\"lowPriceVolume\":2},"
            + "{\"timestamp\":1792487700,\"avgHighPrice\":null,\"highPriceVolume\":0,\"avgLowPrice\":771000,\"lowPriceVolume\":1},"
            + "{\"timestamp\":1792488000,\"avgHighPrice\":null,\"avgLowPrice\":null}"
            + "]}");
        assertEquals(2, pts.size());
        assertEquals(1792487400L, pts.get(0).ts);
        assertEquals(780000L, pts.get(0).high);
        assertEquals(770000L, pts.get(0).low);
        assertEquals(0L, pts.get(1).high);
        assertEquals(771000L, pts.get(1).low);
        assertTrue(w.parse("{\"error\":\"bad\"}").isEmpty());
    }

    @Test public void dropsOutOfRangePrices() {
        WikiTimeseries w = new WikiTimeseries(null, GSON);
        List<SparklineDto.Point> pts = w.parse("{\"data\":["
            + "{\"timestamp\":1,\"avgHighPrice\":2147483648,\"avgLowPrice\":5},"           // high > int max
            + "{\"timestamp\":2,\"avgHighPrice\":-7,\"avgLowPrice\":2147483647},"           // negative high, low = int max
            + "{\"timestamp\":3,\"avgHighPrice\":100000000000000000000,\"avgLowPrice\":0}," // 1e20 would wrap via getAsLong
            + "{\"timestamp\":4,\"avgHighPrice\":\"abc\",\"avgLowPrice\":1e300}"
            + "]}");
        assertEquals("rows with no valid price are skipped", 2, pts.size());
        assertEquals(0L, pts.get(0).high);
        assertEquals(5L, pts.get(0).low);
        assertEquals(0L, pts.get(1).high);
        assertEquals((long) Integer.MAX_VALUE, pts.get(1).low);
    }

    @Test public void parsesVolumesAndRangeChecksTimestamps() {
        WikiTimeseries w = new WikiTimeseries(null, GSON);
        List<SparklineDto.Point> pts = w.parse("{\"data\":["
            + "{\"timestamp\":1792487400,\"avgHighPrice\":10,\"highPriceVolume\":5,\"avgLowPrice\":9,\"lowPriceVolume\":2},"
            + "{\"timestamp\":1e20,\"avgHighPrice\":10,\"avgLowPrice\":9},"
            + "{\"timestamp\":-5,\"avgHighPrice\":10,\"avgLowPrice\":9},"
            + "{\"timestamp\":\"soon\",\"avgHighPrice\":10,\"avgLowPrice\":9},"
            + "{\"timestamp\":1792487700,\"avgHighPrice\":10,\"highPriceVolume\":-3,\"avgLowPrice\":9,\"lowPriceVolume\":1e12}"
            + "]}");
        assertEquals("bad timestamps dropped", 2, pts.size());
        assertEquals(5L, pts.get(0).highVol);
        assertEquals(2L, pts.get(0).lowVol);
        assertEquals(0L, pts.get(1).highVol);
        assertEquals(0L, pts.get(1).lowVol);
    }

    @Test public void bodyCapRejectsOversizedResponses() throws IOException {
        assertEquals("ok", WikiTimeseries.readCapped(ResponseBody.create(JSON, "ok"), 2));
        try {
            WikiTimeseries.readCapped(ResponseBody.create(JSON, "toolong"), 2);
            fail("over cap");
        } catch (IOException expected) { }
        // No Content-Length: the streamed read is bounded too.
        ResponseBody chunked = ResponseBody.create(JSON, -1, new okio.Buffer().writeUtf8("0123456789"));
        try {
            WikiTimeseries.readCapped(chunked, 5);
            fail("over cap without content-length");
        } catch (IOException expected) { }
        assertEquals(1L << 20, WikiTimeseries.MAX_BODY_BYTES);
    }

    @Test public void identifiesItselfAndSetsCallTimeout() {
        assertTrue(WikiTimeseries.USER_AGENT.startsWith("Coffer"));
        assertTrue(WikiTimeseries.URL.startsWith("https://prices.runescape.wiki/"));
        WikiTimeseries w = new WikiTimeseries(new OkHttpClient(), GSON);
        assertEquals(10_000, w.client().callTimeoutMillis());
    }

    @Test public void asyncLoadDeliversPointsThroughTheCache() throws Exception {
        AtomicReference<String> ua = new AtomicReference<>();
        OkHttpClient fake = new OkHttpClient.Builder().addInterceptor(chain -> {
            ua.set(chain.request().header("User-Agent"));
            assertEquals("5m", chain.request().url().queryParameter("timestep"));
            return response(chain.request(), 200, SAMPLE);
        }).build();
        TimeseriesCache cache = new TimeseriesCache(new WikiTimeseries(fake, GSON), () -> System.nanoTime() / 1_000_000L);
        assertNull("get() returns immediately; the call runs on OkHttp's dispatcher", cache.get(4151, "5m"));
        TimeseriesCache.Series s = await(cache, 4151, "5m");
        assertFalse(s.failed);
        assertEquals(780000L, s.points.get(0).high);
        assertEquals(WikiTimeseries.USER_AGENT, ua.get());
    }

    @Test public void asyncHttpErrorMarksSeriesFailed() throws Exception {
        OkHttpClient fake = new OkHttpClient.Builder()
            .addInterceptor(chain -> response(chain.request(), 503, "{}")).build();
        TimeseriesCache cache = new TimeseriesCache(new WikiTimeseries(fake, GSON), () -> System.nanoTime() / 1_000_000L);
        cache.get(4151, "5m");
        TimeseriesCache.Series s = await(cache, 4151, "5m");
        assertTrue(s.failed);
        assertTrue(s.points.isEmpty());
    }

    @Test public void asyncNetworkFailureReachesCallback() throws Exception {
        OkHttpClient fake = new OkHttpClient.Builder()
            .addInterceptor(chain -> { throw new IOException("offline"); }).build();
        CountDownLatch done = new CountDownLatch(1);
        AtomicReference<Throwable> err = new AtomicReference<>();
        new WikiTimeseries(fake, GSON).load(4151, "5m", new TimeseriesCache.Callback() {
            @Override public void onSuccess(List<SparklineDto.Point> points) { done.countDown(); }
            @Override public void onFailure(Throwable e) { err.set(e); done.countDown(); }
        });
        assertTrue(done.await(5, TimeUnit.SECONDS));
        assertNotNull(err.get());
    }

    private static TimeseriesCache.Series await(TimeseriesCache cache, int id, String step) throws InterruptedException {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        while (System.nanoTime() < deadline) {
            if (!cache.isLoading(id, step)) {
                TimeseriesCache.Series s = cache.get(id, step);
                if (s != null) return s;
            }
            Thread.sleep(10);
        }
        throw new AssertionError("load never completed");
    }

    private static Response response(okhttp3.Request req, int code, String body) {
        return new Response.Builder().request(req).protocol(Protocol.HTTP_1_1).code(code).message("x")
            .body(ResponseBody.create(JSON, body)).build();
    }
}

