    @Test public void hiddenFrameClearsStaleHover() {
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, m, args) -> "getGameState".equals(m.getName()) ? GameState.LOGGED_IN
                : m.getReturnType() == int.class ? (Object) 0 : m.getReturnType() == long.class ? (Object) 0L : null);
        OfferChartOverlay overlay = new OfferChartOverlay(client, null, () -> false);
        overlay.mouseListener().mouseMoved(new MouseEvent(new javax.swing.JPanel(), MouseEvent.MOUSE_MOVED, 0, 0, 200, 90, 0, false));
        assertEquals(new Point(200, 90), overlay.hover());
        assertNull(overlay.render(null));
        assertNull("hidden overlay drops the hover point", overlay.hover());
    }

    @Test public void hoverTracksOnlyWhileLoggedInAndClearsOnExit() {
        GameState[] state = {GameState.LOGIN_SCREEN};
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, m, args) -> "getGameState".equals(m.getName()) ? state[0] : null);
        OfferChartOverlay overlay = new OfferChartOverlay(client, null, () -> true);
        MouseEvent move = new MouseEvent(new javax.swing.JPanel(), MouseEvent.MOUSE_MOVED, 0, 0, 200, 90, 0, false);
        overlay.mouseListener().mouseMoved(move);
        assertNull(overlay.hover());
        state[0] = GameState.LOGGED_IN;
        overlay.mouseListener().mouseMoved(move);
        assertEquals(new Point(200, 90), overlay.hover());
        assertFalse("hover never consumes", move.isConsumed());
        overlay.mouseListener().mouseExited(new MouseEvent(new javax.swing.JPanel(), MouseEvent.MOUSE_EXITED, 0, 0, 0, 0, 0, false));
        assertNull(overlay.hover());
    }

    private static net.runelite.api.GrandExchangeOffer offer(int itemId, long price) {
        return (net.runelite.api.GrandExchangeOffer) Proxy.newProxyInstance(
            net.runelite.api.GrandExchangeOffer.class.getClassLoader(), new Class<?>[]{net.runelite.api.GrandExchangeOffer.class},
            (proxy, m, args) -> {
                switch (m.getName()) {
                    case "getItemId": return itemId;
                    case "getPrice": return price;
                    default: return m.getReturnType() == int.class ? 0 : m.getReturnType() == long.class ? 0L : null;
                }
            });
    }

    static SparklineDto.Point pt(long ts, long high, long low) {
        SparklineDto.Point p = new SparklineDto.Point();
        p.ts = ts; p.high = high; p.low = low; p.mid = (high + low) / 2.0;
        return p;
    }

    private static List<String> labels() {
        List<String> out = new ArrayList<>();
        for (OfferChartRange r : OfferChartRange.values()) out.add(r.label);
        return out;
    }
}

package com.gecopilot.client.ui;

import com.gecopilot.client.api.QuoteDto;
import net.runelite.client.ui.overlay.components.PanelComponent;
import org.junit.Test;

import javax.imageio.ImageIO;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

import static org.junit.Assert.*;

/** Renders the real overlay panel headlessly and writes the two warning screenshots. */
public class OfferOverlayRenderTest {
    @Test public void rendersSellAndBuyWarnings() throws Exception {
        Path dir = Paths.get(System.getProperty("overlay.out", "build/overlay-screenshots"));
        Files.createDirectories(dir);

        QuoteDto sellQuote = quote(2_000_000, 2_400_000, 2_001_000, 2_399_000, 350_000);
        OfferPriceWarning.Warning sell = OfferPriceWarning.evaluate(false, 1_800_000, sellQuote.buy, sellQuote.sell);
        assertNotNull(sell);
        BufferedImage sellImg = render(sellQuote, sell);
        assertTrue("sell panel pixels=" + paintedCount(sellImg), paintedCount(sellImg) > 20);
        ImageIO.write(sellImg, "png", dir.resolve("overlay-sell-warning.png").toFile());

        QuoteDto buyQuote = quote(2_000_000, 2_400_000, 2_001_000, 2_399_000, 350_000);
        OfferPriceWarning.Warning buy = OfferPriceWarning.evaluate(true, 2_800_000, buyQuote.buy, buyQuote.sell);
        assertNotNull(buy);
        assertEquals(400_000, buy.gapGp);
        BufferedImage buyImg = render(buyQuote, buy);
        assertTrue("buy panel pixels=" + paintedCount(buyImg), paintedCount(buyImg) > 20);
        ImageIO.write(buyImg, "png", dir.resolve("overlay-buy-warning.png").toFile());

        assertNotEquals(fingerprint(sellImg), fingerprint(buyImg));
    }

    @Test public void rendersThinMarginWarning() throws Exception {
        Path dir = Paths.get(System.getProperty("overlay.out", "build/overlay-screenshots"));
        Files.createDirectories(dir);

        // Adamant arrows: high 28, low 26, after-tax margin 2 gp. Place prices follow QuoteRoutes
        // (margin > 4 bumps a tick; 2 gp does not). The user's bid of 27 is between low and high,
        // so the buy-over-high line stays quiet and only the thin-margin warning shows.
        QuoteDto q = quote(26, 28, 26, 28, 2);
        OfferPriceWarning.ThinMargin thin = OfferPriceWarning.evaluateMargin(true, q.buy, q.sell, 10, 0.3);
        assertNotNull(thin);
        assertEquals(2L, thin.marginGp);
        assertNull(OfferPriceWarning.evaluate(true, 27, q.buy, q.sell));

        PanelComponent panel = new PanelComponent();
        BufferedImage canvas = new BufferedImage(400, 280, BufferedImage.TYPE_INT_ARGB);
        Dimension d = null;
        for (int frame = 0; frame < 2; frame++) {
            Graphics2D g = canvas.createGraphics();
            g.setColor(new Color(18, 18, 18));
            g.fillRect(0, 0, canvas.getWidth(), canvas.getHeight());
            d = GeOfferOverlay.paint(g, panel, q, null, thin);
            g.dispose();
        }
        assertNotNull(d);
        assertTrue(d.width > 0 && d.height > 0);
        int w = Math.min(canvas.getWidth(), d.width + 4);
        int h = Math.min(canvas.getHeight(), d.height + 4);
        BufferedImage crop = canvas.getSubimage(0, 0, w, h);
        BufferedImage scaled = new BufferedImage(w * 2, h * 2, BufferedImage.TYPE_INT_ARGB);
        Graphics2D sg = scaled.createGraphics();
        sg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        sg.drawImage(crop, 0, 0, scaled.getWidth(), scaled.getHeight(), null);
        sg.dispose();
        assertTrue("thin panel pixels=" + paintedCount(scaled), paintedCount(scaled) > 20);
        ImageIO.write(scaled, "png", dir.resolve("overlay-thin-margin.png").toFile());
    }

    private static QuoteDto quote(int low, int high, int placeBuy, int placeSell, long margin) {
        QuoteDto q = new QuoteDto();
        q.id = 4151;
        q.buy = low;
        q.sell = high;
        q.placeBuy = placeBuy;
        q.placeSell = placeSell;
        q.margin = margin;
        return q;
    }

    private static BufferedImage render(QuoteDto q, OfferPriceWarning.Warning warning) {
        // PanelComponent sizes itself from the previous frame's children, same as in the client
        // (the overlay renders every game frame). Paint twice and keep the second frame.
        PanelComponent panel = new PanelComponent();
        BufferedImage canvas = new BufferedImage(360, 240, BufferedImage.TYPE_INT_ARGB);
        Dimension d = null;
        for (int frame = 0; frame < 2; frame++) {
            Graphics2D g = canvas.createGraphics();
            g.setColor(new Color(18, 18, 18));
            g.fillRect(0, 0, canvas.getWidth(), canvas.getHeight());
            d = GeOfferOverlay.paint(g, panel, q, warning);
            g.dispose();
        }
        assertNotNull(d);
        assertTrue(d.width > 0 && d.height > 0);
        int w = Math.min(canvas.getWidth(), d.width + 4);
        int h = Math.min(canvas.getHeight(), d.height + 4);
        BufferedImage crop = canvas.getSubimage(0, 0, w, h);
        BufferedImage scaled = new BufferedImage(w * 2, h * 2, BufferedImage.TYPE_INT_ARGB);
        Graphics2D sg = scaled.createGraphics();
        sg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        sg.drawImage(crop, 0, 0, scaled.getWidth(), scaled.getHeight(), null);
        sg.dispose();
        return scaled;
    }

    private static int paintedCount(BufferedImage img) {
        int seen = 0;
        for (int y = 0; y < img.getHeight(); y += 3) {
            for (int x = 0; x < img.getWidth(); x += 3) {
                int argb = img.getRGB(x, y);
                if ((argb >>> 24) == 0) continue;
                if ((argb & 0xffffff) != 0x121212) seen++;
            }
        }
        return seen;
    }

    private static int fingerprint(BufferedImage img) {
        int h = 0;
        for (int y = 0; y < img.getHeight(); y += 4)
            for (int x = 0; x < img.getWidth(); x += 4)
                h = 31 * h + img.getRGB(x, y);
        return h;
    }
}

package com.gecopilot.client.ui;

import org.junit.Test;
import static org.junit.Assert.*;

public class OfferPriceWarningTest {
    @Test public void sellBelowWhatBuyersPayWarnsWithGap() {
        OfferPriceWarning.Warning w = OfferPriceWarning.evaluate(false, 900, 1000, 1200);
        assertNotNull(w);
        assertFalse(w.buy);
        assertEquals(900, w.offerPrice);
        assertEquals(1000, w.marketPrice);
        assertEquals(100, w.gapGp);
        assertEquals(10.0, w.gapPct, 0.001);
        assertEquals("Sell under buyers", w.headline());
        assertTrue(w.detail().contains("100"));
        assertTrue(w.detail().contains("10.0%"));
        assertTrue(w.detail().contains("under"));
    }

    @Test public void sellAtOrAboveTheLowIsFine() {
        assertNull(OfferPriceWarning.evaluate(false, 1000, 1000, 1200));
        assertNull(OfferPriceWarning.evaluate(false, 1100, 1000, 1200)); // under the high, still above buyers
    }

    @Test public void buyAboveMarketHighWarnsWithGap() {
        OfferPriceWarning.Warning w = OfferPriceWarning.evaluate(true, 1500, 1000, 1200);
        assertNotNull(w);
        assertTrue(w.buy);
        assertEquals(1200, w.marketPrice);
        assertEquals(300, w.gapGp);
        assertEquals(25.0, w.gapPct, 0.001);
        assertEquals("Buy over market", w.headline());
        assertTrue(w.detail().contains("25.0%"));
        assertTrue(w.detail().contains("over"));
    }

    @Test public void buyAtOrBelowTheHighIsFine() {
        assertNull(OfferPriceWarning.evaluate(true, 1200, 1000, 1200));
        assertNull(OfferPriceWarning.evaluate(true, 1100, 1000, 1200));
    }

    @Test public void missingOrZeroPricesDoNotWarn() {
        assertNull(OfferPriceWarning.evaluate(false, 0, 1000, 1200));
        assertNull(OfferPriceWarning.evaluate(false, 500, 0, 1200));
        assertNull(OfferPriceWarning.evaluate(true, 5000, 1000, 0));
        assertNull(OfferPriceWarning.evaluate(true, 0, 1000, 1200));
    }

    @Test public void adamantArrowsMarginIsTooThinOnABuy() {
        // High 28, low 26. Tax is 0 under 50 gp, so after-tax margin is 2 gp (~7.7% of 26).
        // That clears the 0.3% ROI default and fails the 10 gp margin default.
        OfferPriceWarning.ThinMargin w = OfferPriceWarning.evaluateMargin(true, 26, 28, 10, 0.3);
        assertNotNull(w);
        assertEquals(2L, w.marginGp);
        assertEquals(2.0 * 100.0 / 26.0, w.marginPct, 0.001);
        assertEquals("Margin too thin to flip", w.headline());
        assertTrue(w.detail().contains("2 gp"));
        assertTrue(w.detail().contains("7.7%"));
        assertTrue(w.detail().contains("after tax"));
    }

    @Test public void thinMarginDoesNotWarnOnASellSetup() {
        assertNull(OfferPriceWarning.evaluateMargin(false, 26, 28, 10, 0.3));
    }

    @Test public void marginAtTheUsersThresholdsIsFine() {
        // 197 gp on a 10_000 buy is 1.97%, above both defaults.
        assertNull(OfferPriceWarning.evaluateMargin(true, 10_000, 10_405, 10, 0.3));
        // sell 10_214 taxes 204, so margin is exactly 10 gp and exactly 0.1%. FlipEngine keeps `==`.
        assertNull(OfferPriceWarning.evaluateMargin(true, 10_000, 10_214, 10, 0.1));
        OfferPriceWarning.ThinMargin underRoi = OfferPriceWarning.evaluateMargin(true, 10_000, 10_214, 10, 0.11);
        assertNotNull(underRoi);
        assertEquals(10L, underRoi.marginGp);
    }

    @Test public void unprofitableSpreadWarns() {
        // 100/100 after 2% tax is -2 gp.
        OfferPriceWarning.ThinMargin w = OfferPriceWarning.evaluateMargin(true, 100, 100, 10, 0.3);
        assertNotNull(w);
        assertEquals(-2L, w.marginGp);
        assertTrue(w.detail().contains("-2"));
    }

    @Test public void roiBelowTheUsersMinimumWarnsEvenWhenGpClears() {
        // ~201 gp on a 100_000 buy is 0.20%, under a 0.3% floor, over a 10 gp floor.
        OfferPriceWarning.ThinMargin w = OfferPriceWarning.evaluateMargin(true, 100_000, 102_245, 10, 0.3);
        assertNotNull(w);
        assertTrue(w.marginGp >= 10);
        assertTrue(w.marginPct < 0.3);
    }

    @Test public void missingMarketDoesNotWarnOnMargin() {
        assertNull(OfferPriceWarning.evaluateMargin(true, 0, 28, 10, 0.3));
        assertNull(OfferPriceWarning.evaluateMargin(true, 26, 0, 10, 0.3));
    }

    @Test public void buyOverHighAndThinMarginAreIndependent() {
        // Bid 30 is over the high of 28, and the 2 gp spread is also too thin.
        assertNotNull(OfferPriceWarning.evaluate(true, 30, 26, 28));
        assertNotNull(OfferPriceWarning.evaluateMargin(true, 26, 28, 10, 0.3));
        // Bid 27 sits between 26 and 28, so only the thin-margin line fires.
        assertNull(OfferPriceWarning.evaluate(true, 27, 26, 28));
        assertNotNull(OfferPriceWarning.evaluateMargin(true, 26, 28, 10, 0.3));
    }
}

package com.gecopilot.client.ui;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PreviewSavePromptTest {
    @Test public void hiddenUntilFirstCardChoice() {
        PreviewSavePrompt p = new PreviewSavePrompt();
        assertEquals(PreviewSavePrompt.Phase.HIDDEN, p.phase());
        assertFalse(p.onFlipChosen(0));
        assertEquals(PreviewSavePrompt.Phase.HIDDEN, p.phase());
        assertTrue(p.onFlipChosen(4151));
        assertEquals(PreviewSavePrompt.Phase.ASK, p.phase());
        assertEquals(4151, p.pickId());
        // Later choices do not re-open or replace the first pick.
        assertFalse(p.onFlipChosen(2));
        assertEquals(4151, p.pickId());
    }

    @Test public void saveContinuesIntoFieldsAndDismissSticks() {
        PreviewSavePrompt p = new PreviewSavePrompt();
        p.onFlipChosen(4151);
        p.saveClicked();
        assertEquals(PreviewSavePrompt.Phase.FIELDS, p.phase());
        assertFalse(p.onFlipChosen(9));
        p.continueWithoutSaving();
        assertEquals(PreviewSavePrompt.Phase.DISMISSED, p.phase());
        assertEquals(0, p.pickId());
        assertFalse(p.onFlipChosen(4151));
        assertEquals(PreviewSavePrompt.Phase.DISMISSED, p.phase());
    }

    @Test public void resetReturnsToHidden() {
        PreviewSavePrompt p = new PreviewSavePrompt();
        p.onFlipChosen(1);
        p.reset();
        assertEquals(PreviewSavePrompt.Phase.HIDDEN, p.phase());
        assertTrue(p.onFlipChosen(2));
    }
}

package com.gecopilot.client.ui;

import org.junit.Test;

import static com.gecopilot.client.ui.RefreshStatus.State.*;
import static org.junit.Assert.*;

public class RefreshStatusTest {
    private static final long NOW = 10_000_000_000L;

    @Test public void updatingThenUpdated() {
        assertEquals("Updating\u2026", RefreshStatus.text(UPDATING, NOW - 600_000, NOW));
        assertEquals("Updated just now", RefreshStatus.text(OK, NOW, NOW));
    }

    @Test public void failureSaysHowOldTheDataIs() {
        assertEquals("Last updated 1m ago", RefreshStatus.text(FAILED, NOW - 5_000, NOW));
        assertEquals("Last updated 12m ago", RefreshStatus.text(FAILED, NOW - 12 * 60_000L - 30_000, NOW));
        assertEquals("Last updated 59m ago", RefreshStatus.text(FAILED, NOW - 59 * 60_000L, NOW));
        assertEquals("Last updated 2h ago", RefreshStatus.text(FAILED, NOW - 150 * 60_000L, NOW));
        assertEquals("Last updated 3d ago", RefreshStatus.text(FAILED, NOW - 3 * 24 * 3_600_000L, NOW));
        assertEquals("Not updated yet", RefreshStatus.text(FAILED, 0, NOW));
    }

    @Test public void idleKeepsTheRowHeight() {
        assertEquals(" ", RefreshStatus.text(IDLE, 0, NOW));
    }

    @Test public void widestTextCoversEveryState() {
        String[] all = {
            RefreshStatus.text(UPDATING, 0, NOW), RefreshStatus.text(OK, NOW, NOW),
            RefreshStatus.text(FAILED, NOW - 59 * 60_000L, NOW), RefreshStatus.text(FAILED, NOW - 23 * 3_600_000L, NOW),
            RefreshStatus.text(FAILED, NOW - 99 * 24 * 3_600_000L, NOW), RefreshStatus.text(FAILED, 0, NOW)};
        for (String t : all) assertTrue(t, t.length() <= RefreshStatus.WIDEST.length());
    }
}

package com.gecopilot.client.ui;

import org.junit.Test;

import java.util.Locale;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class SessionGuideTest {
    @Test public void stagesFollowGeThenOfferThenTrade() {
        assertEquals(SessionGuide.Stage.OPEN_GE, SessionGuide.stage(false, false, false));
        assertEquals(SessionGuide.Stage.PLACE_OFFER, SessionGuide.stage(true, false, false));
        // Offer already captured, even if this client has not reported offersKnown.
        assertEquals(SessionGuide.Stage.WAIT_FILL, SessionGuide.stage(false, true, false));
        assertEquals(SessionGuide.Stage.DONE, SessionGuide.stage(false, false, true));
        assertEquals(SessionGuide.Stage.DONE, SessionGuide.stage(true, true, true));
    }

    @Test public void advanceDoesNotRegress() {
        assertEquals(SessionGuide.Stage.PLACE_OFFER,
            SessionGuide.advance(SessionGuide.Stage.PLACE_OFFER, SessionGuide.Stage.OPEN_GE));
        assertEquals(SessionGuide.Stage.DONE,
            SessionGuide.advance(SessionGuide.Stage.DONE, SessionGuide.Stage.OPEN_GE));
        assertEquals(SessionGuide.Stage.WAIT_FILL,
            SessionGuide.advance(null, SessionGuide.Stage.WAIT_FILL));
    }

    @Test public void bannerNamesTheNextAction() {
        assertEquals("Next: open the Grand Exchange.", SessionGuide.banner(SessionGuide.Stage.OPEN_GE, null, 0));
        assertEquals("Next: place or view an offer in the GE.",
            SessionGuide.banner(SessionGuide.Stage.PLACE_OFFER, "", 0));
        assertEquals("Next: in the GE, buy Whip @ " + String.format(Locale.US, "%,d", 1200) + ".",
            SessionGuide.banner(SessionGuide.Stage.PLACE_OFFER, "Whip", 1200));
        assertEquals("Offer synced. Sell it when it fills — see Positions.",
            SessionGuide.banner(SessionGuide.Stage.WAIT_FILL, "Whip", 1200));
        assertNull(SessionGuide.banner(SessionGuide.Stage.DONE, "Whip", 1200));
    }

    @Test public void toastOnlyOnAdvance() {
        assertNull(SessionGuide.transitionToast(null, SessionGuide.Stage.OPEN_GE));
        assertNull(SessionGuide.transitionToast(SessionGuide.Stage.OPEN_GE, SessionGuide.Stage.OPEN_GE));
        assertEquals("GE is open. Place or view an offer.",
            SessionGuide.transitionToast(SessionGuide.Stage.OPEN_GE, SessionGuide.Stage.PLACE_OFFER));
        assertEquals("Offer synced. Check Positions.",
            SessionGuide.transitionToast(SessionGuide.Stage.PLACE_OFFER, SessionGuide.Stage.WAIT_FILL));
        assertEquals("First trade recorded.",
            SessionGuide.transitionToast(SessionGuide.Stage.WAIT_FILL, SessionGuide.Stage.DONE));
        assertNull(SessionGuide.transitionToast(SessionGuide.Stage.DONE, SessionGuide.Stage.OPEN_GE));
    }

    @Test public void emptyStatesNameTheStage() {
        assertEquals("No offers yet. Open the Grand Exchange.",
            SessionGuide.emptyPositions(SessionGuide.Stage.OPEN_GE));
        assertEquals("No offer yet. Buy the top Finder pick in the GE.",
            SessionGuide.emptyPositions(SessionGuide.Stage.PLACE_OFFER));
        assertEquals("No open offers.", SessionGuide.emptyPositions(SessionGuide.Stage.DONE));
        assertEquals("No flips right now.", SessionGuide.emptyFlips(null));
    }
}

package com.gecopilot.client.ui;

import com.gecopilot.client.api.ServiceStatusDto;
import com.gecopilot.client.api.StatusMonitor;
import com.gecopilot.client.api.PollPolicy;
import org.junit.Test;

import javax.swing.SwingUtilities;

import static org.junit.Assert.*;

public class StatusBannerTest {
    private static StatusMonitor.Banner banner(String level, String message, Boolean db) {
        StatusMonitor m = new StatusMonitor(new PollPolicy(() -> 0L, () -> false), () -> 0L);
        ServiceStatusDto s = level == null && message == null && db == null ? null : new ServiceStatusDto();
        if (s != null) { s.level = level; s.message = message; s.db = db; }
        assertTrue(m.tryStart());
        return m.attempt(() -> s).banner;
    }

    private static void flush() throws Exception { SwingUtilities.invokeAndWait(() -> { }); }

    @Test public void bannerShowsOnEveryCardAndHidesTheSmallConnNotice() throws Exception {
        System.setProperty("java.awt.headless", "true");
        CloudPanel[] holder = new CloudPanel[1];
        SwingUtilities.invokeAndWait(() -> holder[0] = new CloudPanel(null));
        CloudPanel p = holder[0];
        assertNull(p.serviceStatusText());

        p.setConnNotice("Can't reach Coffer \u2014 retrying\u2026");
        flush();
        assertEquals("Can't reach Coffer \u2014 retrying\u2026", p.connNoticeText());

        p.setServiceStatus(banner(null, null, null)); // unreachable -> auto outage
        flush();
        assertEquals(StatusMonitor.DEFAULT_OUTAGE, p.serviceStatusText());
        assertNull("the banner already says it", p.connNoticeText());

        p.setServiceStatus(null); // recovered
        flush();
        assertNull(p.serviceStatusText());
        assertEquals("the conn notice comes back if still unreachable", "Can't reach Coffer \u2014 retrying\u2026", p.connNoticeText());
    }

    @Test public void serverTextIsPlainNotHtml() throws Exception {
        System.setProperty("java.awt.headless", "true");
        StatusBanner[] holder = new StatusBanner[1];
        SwingUtilities.invokeAndWait(() -> holder[0] = new StatusBanner());
        StatusMonitor.Banner b = banner("info", "<html><b>hi</b></html>", true);
        SwingUtilities.invokeAndWait(() -> holder[0].show(b));
        assertEquals("<html><b>hi</b></html>", holder[0].shownText()); // shown literally in a JTextArea
    }

    @Test public void sinceIsRelative() {
        long now = java.time.Instant.parse("2026-10-19T21:00:00Z").toEpochMilli();
        assertEquals("Since 12m ago", StatusBanner.sinceText("2026-10-19T20:48:00Z", now));
        assertEquals("Since 3h ago", StatusBanner.sinceText("2026-10-19T18:00:00Z", now));
        assertEquals("Since 2d ago", StatusBanner.sinceText("2026-10-17T20:00:00Z", now));
        assertEquals("Since 1m ago", StatusBanner.sinceText("2026-10-19T20:59:50Z", now));
        assertEquals("future (clock skew) reads as 1m", "Since 1m ago", StatusBanner.sinceText("2026-10-19T22:00:00Z", now));
        assertNull(StatusBanner.sinceText("nope", now));
        assertNull(StatusBanner.sinceText(null, now));
    }

    @Test public void linkLabelShowsWhereItGoes() {
        assertEquals("Copy link: meetcoffer.com/status", StatusBanner.linkLabel("https://meetcoffer.com/status/"));
        assertEquals("Copy link: x.example/a", StatusBanner.linkLabel("https://x.example/a?utm=1#top"));
        String longOne = StatusBanner.linkLabel("https://status.example.com/incidents/2026/10/19/neon-paused-database");
        assertEquals("Copy link: ".length() + StatusBanner.LINK_CHARS, longOne.length());
        assertTrue(longOne.endsWith("\u2026"));
    }
}

package com.gecopilot.client.ui;

import com.gecopilot.client.api.PositionDto;
import com.gecopilot.client.api.WatchDto;
import org.junit.Test;

import static org.junit.Assert.*;

public class WatchCostLabelTest {
    @Test
    public void fullCostKeepsPlainLabel() {
        WatchDto w = new WatchDto();
        w.buyCost = 120;
        assertEquals("server sent no qty", "Your cost", CloudPanel.costLabel(w));
        w.trackedQty = 42; w.heldQty = 42;
        assertEquals("Avg cost (42 known)", CloudPanel.costLabel(w));
        assertEquals(120, CloudPanel.knownCost(w));
    }

    @Test
    public void partialCostSaysHowManyAreKnown() {
        WatchDto w = new WatchDto();
        w.knownCost = 153234; w.partialCost = true; w.trackedQty = 22; w.heldQty = 42;
        assertEquals("Avg cost (22 known)", CloudPanel.costLabel(w));
        assertEquals("Cost known for 22 of 42", CloudPanel.costKnownLine(w));
        assertEquals(153234, CloudPanel.knownCost(w));
    }

    @Test
    public void partialFromAnOlderServerFallsBackToBuyCost() {
        WatchDto w = new WatchDto();
        w.buyCost = 153234; w.partialCost = true; w.trackedQty = 22; w.heldQty = 42;
        assertEquals(153234, CloudPanel.knownCost(w));
    }

    @Test
    public void signedAmounts() {
        assertEquals("0 gp", CloudPanel.signedGp(0));
        assertEquals("+4,948 gp", CloudPanel.signedGp(4_948));
        assertEquals(CloudPanel.MINUS + "890,318 gp", CloudPanel.signedGp(-890_318));
        assertEquals(CloudPanel.NEUTRAL, CloudPanel.edgeColor(0));
        assertEquals(CloudPanel.WARN, CloudPanel.edgeColor(-1));
        // True minus only if the RuneLite panel fonts have the glyph; they currently do not, so hyphen.
        boolean has = net.runelite.client.ui.FontManager.getRunescapeSmallFont().canDisplay('\u2212')
            && net.runelite.client.ui.FontManager.getRunescapeFont().canDisplay('\u2212');
        assertEquals(has ? "\u2212" : "-", CloudPanel.MINUS);
    }

    @Test
    public void adviceColourFollowsMeaning() {
        PositionDto p = new PositionDto();
        p.warn = true; p.verdict = "REPRICE";
        assertEquals(CloudPanel.WARN, CloudPanel.adviceColor(p));
        p = new PositionDto();
        p.partialCost = true; p.verdict = "CHECK";
        assertEquals(CloudPanel.PARTIAL, CloudPanel.adviceColor(p));
        p = new PositionDto();
        p.verdict = "HOLD";
        assertEquals(CloudPanel.NEUTRAL, CloudPanel.adviceColor(p));
        assertEquals(0xFF7B72, CloudPanel.WARN.getRGB() & 0xFFFFFF);
        assertEquals(0xFFB020, CloudPanel.PARTIAL.getRGB() & 0xFFFFFF);
        assertEquals(0xA8A8A8, CloudPanel.NEUTRAL.getRGB() & 0xFFFFFF);
        assertEquals(CloudPanel.NEUTRAL, CloudPanel.verdictColor("CHECK"));
        assertEquals(CloudPanel.PARTIAL, CloudPanel.verdictColor("REPRICE"));
        assertEquals(CloudPanel.WARN, CloudPanel.verdictColor("CUT"));
    }
}
